(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["pt"] = {"ui":{"skip":"Saltar para o conteúdo","back":"← Voltar ao AI-gile","lang.button":"Idioma: {name}","lang.dialog":"Escolhe um idioma","lang.search":"Pesquisar idiomas","lang.none":"Nenhum idioma encontrado","lang.notYet":"{name} ainda não está traduzido","theme.aria":"Mudar de tema: claro, escuro ou preto","theme.toLight":"Mudar para o tema claro","theme.toDark":"Mudar para o tema escuro","theme.toBlack":"Mudar para o tema preto (preto a sério, ideal para ecrãs OLED)","words.underline":"Sublinhar estas palavras na página","words.underlineHelp":"Passa o rato ou toca numa palavra pontilhada para veres o que significa.","words.col.todo":"Cartões escolhidos para agora: a equipa começa por estes a seguir.","words.col.doing":"Uma IA está a trabalhar neste cartão neste momento.","words.col.review":"Uma IA acabou o trabalho; outra verifica-o antes de chegar a ti.","words.col.verify":"À tua espera: experimenta e diz se funciona.","words.col.team":"As tuas notas ou respostas, à espera de que a equipa as apanhe.","words.col.done":"Concluído e aceite.","index.title":"AI-gile: a tua equipa de dev com IA, num só quadro","index.description":"O AI-gile é um quadro kanban para equipas de código com IA. Elas trabalham enquanto dormes; recebes uma pilha curta de coisas para decidir, testar e aceitar.","hero.logoAlt":"Ícone do quadro AI-gile","hero.h1.html":"A tua equipa de dev com IA, num só&nbsp;quadro.","hero.alpha":"🐣 Pré-alfa fechado","hero.alphaTitle":"Cedo e inacabado: obrigado por experimentares!","hero.lede":"Constroem enquanto dormes. Acordas com uma pilha curta: algumas perguntas, algumas coisas para testar, um ou dois diamantes roxos. Clica, aceita, volta ao teu café.","dl.windows":"Aplicação para Windows","dl.browser":"Usar no navegador","dl.messenger":"📱 Messenger para o teu telemóvel","dl.soon":"Em breve","dl.notify":"🔔 Avisem-me quando abrir","dl.notifySmall":"Alfa ou beta","hero.secondary":"Ágil, mas a equipa nunca precisa de café em pé para a reunião diária. (Fazem-na na mesma.)","pitch.h2":"O AI-gile em quantas palavras quiseres","pitch.lede":"Escolhe um tamanho, de uma palavra a 144. Cada tamanho é uma descrição própria, escrita para ele. Arrasta o cursor ou usa as setas do teclado.","pitch.rangeLabel":"Tamanho em palavras","pitch.dice":"🎲 outra versão","pitch.words.one":"{n} palavra","pitch.words.other":"{n} palavras","pitch.letters.one":"{n} letra","pitch.letters.other":"{n} letras","pitch.chars.one":"{n} caráter","pitch.chars.other":"{n} carateres","count.line.html.one":"{n} cartão no quadro neste momento","count.line.html.other":"{n} cartões no quadro neste momento","people.humans.html.one":"👥 {n} humano","people.humans.html.other":"👥 {n} humanos","people.agents.html.one":"🤖 {n} agente","people.agents.html.other":"🤖 {n} agentes","people.working.html.one":"⚡ {n} a trabalhar neste momento","people.working.html.other":"⚡ {n} a trabalhar neste momento","pre.title":"AI-gile: há algo a ser construído","pre.description":"Há algo a ser construído aqui: um quadro onde equipas de IA constroem o que pedes e te vão ensinando pelo caminho. Por agora, pré-alfa fechado entre amigos.","pre.h1":"Há algo a ser construído aqui. 🤫","pre.line":"Um quadro onde equipas de IA constroem o que pedes e te vão ensinando pelo caminho. Por agora, pré-alfa fechado entre amigos.","pre.btn":"🔔 Avisem-me quando abrir","pre.peek":"Atrás do vidro: o quadro verdadeiro, em direto. Cada cartão é uma barra colorida.","pre.peekFake":"Atrás do vidro: assim é um quadro a trabalhar.","pre.night":"🌙 O vigilante noturno está ao comando · 😴 o humano está a descansar","features.aria":"O que faz","f.pile.h":"Uma pilha só para ti","f.pile.html":"<b>Para ti</b> reúne tudo o que está à tua espera, em todos os projetos: perguntas, coisas para testar, tarefas que só um humano pode fazer. A tua fila diz o que vem a seguir e quanto tempo demora.","f.sleep.h":"Equipas que trabalham enquanto dormes","f.sleep.p":"Cada projeto tem um líder e uma equipa de agentes de IA. Comenta num cartão e a equipa acorda, faz o trabalho e devolve-o com passos que um humano cansado consegue seguir.","f.tester.h":"Um testador de IA verifica primeiro","f.tester.p":"Antes de chegar a ti, um testador segue os passos numa cópia da aplicação e mostra o que viu, com uma captura de ecrã. Passa pelos aprovados e aceita com um clique.","f.proof.h":"Provas, não promessas","f.proof.p":"Cada entrega mostra o que mudou: os ficheiros, o diff, as capturas de ecrã. Sem abrir cada aplicação para ver se já está pronto.","f.chat.h":"Conversa com os teus líderes","f.chat.p":"Uma barra ao estilo do Discord: um ícone por projeto, diamantes roxos para o que precisa de ti. Manda uma ideia a um líder; ele transforma-a em cartões e num plano, com um botão ✅ Go.","f.tidy.h":"Mantém-se arrumado","f.tidy.p":"Cartões parecidos juntam-se num só, títulos confusos são corrigidos e uma verificação de tokens mantém o código enxuto. Menos coisas para alternar, menos em que pensar.","f.private.h":"Teu, no teu computador","f.private.li1":"O quadro corre na tua própria máquina e só responde a ti.","f.private.li2":"As DMs privadas entre pessoas têm encriptação de ponta a ponta.","f.private.li3":"Sem contas, sem rastreadores, sem cookies.","f.lang.h":"Na tua língua","f.lang.p":"Mais de 120 idiomas, do holandês, galês e japonês ao pirata, Yoda e klingon, com uma troca rápida para inglês no jargão técnico.","f.service.h":"De uma ideia a um serviço a sério","f.service.p":"Construíste com IA algo que as pessoas já usam? Marca-o como serviço e o quadro ajuda-te a geri-lo bem: verificações de disponibilidade, uma página de estado pública, incidentes com relatório, alterações que precisam de um Avançar, cópias de segurança verificadas todos os dias. A Ajuda ensina cada passo pelo caminho.","msgr.h2":"AI-gile Messenger: a tua equipa no bolso","msgr.p1":"Fala com a tua equipa de IA sem abrir o quadro. Conversa com os líderes dos teus projetos e com os teus amigos, vê os passos de teste de um cartão e responde-lhes, tudo a partir do telemóvel.","msgr.p2":"Para o emparelhar, digitaliza um código QR no teu quadro. Primeira vez? Um chat de demonstração simpático mostra-te tudo.","msgr.when":"Primeiro Android, depois uma versão web para telemóveis e iPhone.","msgr.who":"O teu líder de projeto","msgr.b1":"A correção do modo escuro está pronta. Queres os passos de teste?","msgr.b2":"Sim, por favor!","msgr.b3":"1. Abre as Definições. 2. Escolhe Escuro. Parece-te bem?","tl.aria":"Cronologia, da primeira conversa ao plano","tl.h2":"Da primeira conversa ao que vem a seguir","tl.lede":"Datas e horas reais, no teu fuso horário. Depois de hoje é o plano, sem datas prometidas.","tl.today":"Hoje","tl.planned":"planeado","tl.doing":"em curso","tl.cards.one":"{n} cartão","tl.cards.other":"{n} cartões","join.h2":"Junta-te","join.lede":"O AI-gile está a ser construído por um esquisitão barbudo com AuDHD e algumas batalhas com a saúde mental, e por muitos agentes pacientes. Por agora é privado, num alfa fechado com amigos. Queres experimentar quando abrir?","join.btn":"Registar interesse","join.small":"Escrevemos-te por e-mail, mais nada","footer.tag":"AI-gile. Sem rastreadores, sem cookies, sem café em pé.","footer.licence":"Licença comercial","footer.status":"Estado","footer.privacy":"O que guardamos","footer.thanks":"Chamadas graças ao ChilledChat","form.sending":"A enviar…","form.failed":"Não resultou: tenta outra vez mais tarde.","form.offline":"Não foi possível contactar o AI-gile: tenta outra vez mais tarde.","form.keep":"Só usamos isto para te responder e depois apagamos. Sem rastreadores, sem cookies.","form.keepLink":"O que guardamos","interest.title":"AI-gile: avisem-me quando o alfa abrir","interest.description":"Deixa o teu e-mail para saberes quando o alfa ou beta fechado do AI-gile abrir.","interest.h1":"🔔 Avisem-me quando abrir","interest.lede":"O AI-gile está em pré-alfa fechado. Deixa o teu e-mail e escrevemos uma vez, quando houver lugar para ti.","interest.email":"O teu e-mail","interest.which":"Que teste?","interest.alpha":"Alfa fechado: cedo, cru, com muitas mudanças","interest.beta":"Beta: mais firme, mais tarde","interest.both":"Tanto faz, o que vier primeiro","interest.submit":"Pôr-me na lista","interest.thanks":"Obrigado! Estás na lista.","licence.title":"AI-gile: licença comercial","licence.description":"Vais usar o AI-gile na tua empresa? Pede uma licença comercial gratuita.","licence.h1":"📜 Licença comercial","licence.lede":"Vais usar o AI-gile no trabalho? Conta-nos quem és e o que fazes. Se fizer algum bem, a licença é gratuita.","licence.company":"Empresa","licence.website":"Site","licence.what":"O que fazes","licence.how":"Como isso ajuda o mundo","licence.email":"E-mail","licence.submit":"Pedir","licence.thanks":"Obrigado! Respondemos por e-mail.","status.title":"Estado do AI-gile","status.h1":"Estado do AI-gile","status.quiet":"Tudo calmo","status.intro":"O AI-gile está a funcionar neste momento? Esta página verifica o site, a partilha de quadros, as chamadas e a transferência a cada 5 minutos.","status.up":"A funcionar (respondeu em {ms} ms)","status.slow":"Não respondeu à última verificação, a tentar de novo","status.down":"Em baixo: não respondeu às duas últimas verificações","status.svc.web":"Site","status.svc.web.offers":"Este site: o que é o AI-gile e o formulário de interesse","status.svc.boards":"Partilha de quadros","status.svc.boards.offers":"Quadros públicos, mensagens entre amigos e convites","status.svc.calls":"Chamadas","status.svc.calls.offers":"Voz, vídeo e partilha de ecrã no AI-gile","status.svc.download":"Transferência","status.svc.download.offers":"O instalador para Windows e as ligações de convite","status.checking":"A verificar…","status.offline":"Não é possível contactar o serviço de estado neste momento (a tentar de novo)","status.updated":"atualizado {ago}","status.justNow":"agora mesmo","status.min":"há {n} min","status.hours":"há {n} h","status.days":"há {n} d","privacy.title":"AI-gile: o que guardamos","privacy.h1":"O que guardamos","privacy.lede":"Versão curta: só o que nos envias, e não por muito tempo.","privacy.only":"Só o que nos envias: o que escreves num formulário, como o teu e-mail. Mais nada sobre ti.","privacy.sealed":"É selado para que o nosso servidor não o consiga ler: no teu navegador, antes de sair (num navegador mais antigo, no momento em que chega). Só o nosso próprio quadro o consegue abrir.","privacy.server":"É apagado do servidor assim que chega ao nosso quadro. O que lá estiver ao fim de 30 dias é apagado na mesma.","privacy.board":"Guardamo-lo no nosso quadro só até te respondermos e depois apagamo-lo também de lá.","privacy.none":"Sem rastreadores, sem cookies, sem análises.","privacy.local":"O teu idioma e a escolha de tema claro ou escuro ficam no teu próprio navegador. Nunca nos são enviados.","privacy.ask":"Queres que desapareça mais cedo? Responde ao nosso e-mail e diz-nos.","live.h2":"Veja a ser construído, em direto","live.caption":"Cada cartão está escondido: vê a forma do trabalho, não as palavras.","live.watching.one":"em direto: {n} a ver","live.watching.other":"em direto: {n} a ver","live.last.now":"Último cartão movido agora mesmo","live.last.min.one":"Último cartão movido há {n} min","live.last.min.other":"Último cartão movido há {n} min","live.last.hour.one":"Último cartão movido há {n} hora","live.last.hour.other":"Último cartão movido há {n} horas","live.last.day.one":"Último cartão movido há {n} dia","live.last.day.other":"Último cartão movido há {n} dias","live.offline":"O quadro em direto está a fazer uma pausa. Volte em breve.","live.cols":"Backlog|A fazer|Em curso|A equipa verifica|Para testares|Para a equipa|Concluído"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robôs.","Delegado."]},{"n":2,"texts":["Kanban robótico.","Agentes, organizados.","Ideias, construídas."]},{"n":3,"texts":["Kanban para robôs.","Ideias viram funcionalidades.","Kanban de agentes, grátis."]},{"n":5,"texts":["Quadro kanban gerido por agentes.","Tu escreves cartões. Agentes constroem.","Grátis, local, testado, um pouco parvo."]},{"n":8,"texts":["Um kanban grátis onde agentes de IA trabalham.","Escreve uma ideia. Agentes constroem. Tu aceitas.","Ágil para um humano e muitos robôs pacientes."]},{"n":13,"texts":["Um quadro kanban no teu computador, onde agentes de IA pegam nos cartões.","Escreve uma ideia. Uma equipa de agentes constrói. Um testador verifica.","Grátis, sem contas, sem rastreadores: um quadro, uns robôs e tu no comando."]},{"n":21,"texts":["O AI-gile é um quadro kanban para trabalhar com agentes de código de IA. Eles pegam nos cartões; tu testas e aceitas.","Cada projeto tem um líder e uma equipa de agentes de IA. Comenta em qualquer cartão e a equipa mete mãos à obra.","Um quadro pessoal e gratuito que corre no teu próprio computador. Quem trabalha são robôs. Quem diz que sim és tu."]},{"n":34,"texts":["Pões ideias num quadro. Uma equipa de agentes de IA transforma-as em funcionalidades que funcionam, testa tudo e devolve com passos para experimentares. Nada conta como pronto até dizeres que sim.","O AI-gile é um quadro kanban caseiro que o Rich construiu com muita ajuda dos agentes que agora gere. É gratuito, corre no teu computador e é partilhado com amigos, não vendido.","Imagina um quadro kanban normal, com colunas do Backlog até Concluído, só que os cartões são pegos por agentes de IA. Contam o andamento, perguntam quando encravam e esperam sempre pelo teu polegar para cima."]},{"n":55,"texts":["O AI-gile é um quadro kanban em que a equipa é feita de agentes de IA. Cada projeto tem um líder que planeia o trabalho e ajudantes que o constroem. Quando uma funcionalidade fica pronta, um testador de IA experimenta-a e tira uma captura de ecrã, e depois cai na tua pilha. Aceita, ou comenta e eles refazem.","Começou como a maneira de uma pessoa acompanhar várias sessões de código com IA ao mesmo tempo e cresceu até ser um quadro a sério. Corre na tua máquina, não pede conta e não tem rastreadores. É grátis para amigos e curiosos. Também está inacabado, por isso espera arestas e uma surpresa de vez em quando.","Sejamos honestos. Ainda tens de ter as ideias e ainda tens de verificar os resultados. O que o AI-gile faz é tudo o que fica pelo meio: mantém os cartões por ordem, acorda o agente certo quando comentas, mostra exatamente o que mudou e junta tudo numa pilha curta para ti."]},{"n":89,"texts":["O AI-gile é um quadro kanban gratuito que corres no teu próprio computador. Em vez de pessoas, cada projeto tem uma equipa de agentes de IA: um líder que transforma as tuas ideias em cartões e num plano, e ajudantes que pegam nos cartões por ordem de prioridade. Quando algo fica pronto, um testador de IA segue os passos de teste e mostra o que viu. Depois fica à espera numa pilha chamada Para ti. Aceitas, ou comentas e a equipa tenta outra vez. Nada chega a Concluído sem ti.","Alguns recursos que talvez não esperes. Um vigia da noite mantém a coluna A fazer abastecida enquanto dormes, escolhendo cartões que não precisam de resposta tua. Um contador de tokens mostra quanto os agentes gastaram hoje e esta semana, e o Modo Sem Tokens manda-os parar de gastar. Podes conversar com amigos, e as mensagens privadas têm encriptação de ponta a ponta. O quadro fala cerca de 120 idiomas, entre eles holandês, flamengo, pirata e klingon. Nada disto custa um cêntimo, e ninguém te quer vender nada.","O AI-gile é um projeto pequeno e pessoal, não uma empresa. O Rich queria cuidar de vários projetos de código com IA sem abrir cada aplicação para espreitar, por isso ele e os agentes construíram um quadro para isso e depois usaram o quadro para construir o resto dele próprio. Está em pré-alfa fechado, ou seja, funciona, quase sempre, para um punhado de amigos. Não há página de preços, newsletter nem plano de crescimento. Se te parece útil, pede para experimentar quando abrir um pouco mais."]},{"n":144,"texts":["O AI-gile é um quadro kanban para um humano e muitos agentes de IA. Corre no teu próprio computador e é totalmente gratuito. Adicionas projetos, e cada projeto ganha um líder e uma equipa pequena. Conversas com o líder, mais ou menos como no Discord, e descreves uma ideia; o líder transforma-a em cartões e num plano, e espera que carregues em Go. A equipa vai passando pelos cartões por ordem de prioridade, usando uma linha de comandos simples feita para modelos de linguagem. Antes de qualquer coisa voltar para ti, um testador de IA segue os passos numa cópia da aplicação e anexa uma captura de ecrã. O trabalho pronto cai na tua pilha com os ficheiros alterados e o diff. Aceitas, ou deixas um comentário e a equipa acorda e tenta de novo. Só tu podes mover um cartão para Concluído.","Um dia com o AI-gile, mais ou menos. À noite deixas alguns comentários: este botão está no sítio errado, aquela lista devia estar ordenada, podíamos ter um modo escuro. Vais dormir. Os agentes lêem os comentários, fazem as alterações, testam e devolvem-te tudo. Se o A fazer esvazia, o vigia da noite volta a enchê-lo com cartões do backlog que não precisam de resposta tua. De manhã há uma pilha curta: algumas perguntas e algumas coisas para experimentar, cada uma com passos que uma pessoa ensonada consegue seguir e uma captura de ecrã a funcionar. Passas por tudo, aceitas o que está bom e devolves o resto. Um contador de tokens mostra o que tudo isto gastou, e o Modo Sem Tokens existe para as semanas magras. Depois tomas o pequeno-almoço, e aí os agentes ainda não ajudam.","Primeiro, o que o AI-gile não é. Não é uma startup, não está à venda e ninguém recolhe os teus dados. É um quadro gratuito que corre no teu computador, sem contas, sem rastreadores e sem cookies. O que é: um lugar arrumado para ver todos os teus projetos de código com IA de uma vez, com uma equipa de agentes a tratar dos cartões e tu a tomar as decisões. Junta cartões parecidos, corrige títulos confusos e vigia quão enxuto o código se mantém. Fala cerca de 120 idiomas, do holandês e do flamengo ao pirata e ao klingon. Os amigos podem trocar mensagens, em privado e encriptadas. Foi construído pelo Rich e por muitos agentes pacientes, usando-se a si próprio quase sempre. Está em pré-alfa fechado, por isso ainda é cru em alguns pontos. Se te parece divertido, pede com jeitinho e talvez entres mais cedo."]}],"quips":{"1":"Uma palavra. Ousado. Talvez demasiado ousado.","3":"Três palavras. Já mais honesto do que a maioria das páginas de produto.","8":"Oito palavras. Ainda mais curto do que uma reunião diária.","21":"Os tamanhos são story points, já agora. Claro que são.","55":"Cinquenta e cinco palavras. Dois cartões ficaram prontos enquanto lias.","144":"Esta é a longa. Não existe 233. Os agentes foram dormir."}},"timeline":{"first-idea.name":"A primeira ideia","first-idea.line":"A primeiríssima conversa, antes de existir qualquer código.","first-board.name":"Primeiro quadro","first-board.line":"Um quadro que acompanha a sua própria construção: cartões, colunas, arrastar e largar, projetos.","team-roles.name":"Equipa e funções","team-roles.line":"Perfis de agentes, modelos de equipa, espaços e quem faz o quê.","install.name":"Instalação e versões","install.line":"Um zip que um amigo instala, com atualização automática, canais e voltar atrás.","usage-saver.name":"Poupança de uso","usage-saver.line":"Medir o custo de cada execução, manter o código enxuto, poupar o teu limite.","friends.name":"Amigos e partilha","friends.line":"DMs privadas, um relay baralhado, convites, funções e projetos partilhados.","languages.name":"Idiomas","languages.line":"Todo o texto dos ecrãs num ficheiro de idioma, começando pelo holandês e o flamengo.","ai-tester.name":"Testador de IA","ai-tester.line":"Um testador verifica cada entrega primeiro e mostra o que viu.","website.name":"O site","website.line":"aigile.lol, a página de apresentação e esta cronologia.","streaming.name":"Chat e emissão","streaming.line":"Discord, Twitch, OBS, modo streamer, GIFs e emojis.","no-ai.name":"Edição sem IA","no-ai.line":"Um quadro para quem programa sem IA, e quadros públicos.","night-watch.name":"Vigia da noite","night-watch.line":"Um vigia e Scrum Master mantêm as equipas no rumo enquanto dormes.","p-more.name":"Tudo o resto","p-more.line":"Ideias mais pequenas ainda à espera da sua vez.","p-android.name":"Telemóvel e Android","p-android.line":"Acede ao teu quadro pelo telemóvel e, depois, numa aplicação Android nativa.","p-release.name":"Alfa e mais além","p-release.line":"Alfa fechado, o site no ar e depois o beta.","p-languages.name":"Mais idiomas","p-languages.line":"130 línguas e um modo de imersão para quem está a aprender.","p-engines.name":"Mais motores de IA","p-engines.line":"Escolhe Claude, Codex, Gemini, Copilot ou Cursor para cada agente.","p-pro.name":"Prática profissional","p-pro.line":"Etiquetas de risco, portões de merge, cartões de incidente e proteções.","p-self.name":"A cuidar de ti","p-self.line":"Modo cansado, lembretes de autocuidado e 4:20.","p-servers.name":"Servidores e escala","p-servers.line":"Definições globais de servidor, funções e planeamento para crescer.","p-livestream.name":"Extras de emissão","p-livestream.line":"Chat da Twitch, emojis personalizados e uma vista pública em direto."},"words":{"button":"📖 Jargão técnico","h":"📖 Palavras explicadas","intro":"Formação gratuita em linguagem simples: todas as palavras que vais encontrando, de uma primeira ideia até um serviço de que as pessoas dependem, com o Agile, a construção, a segurança e o trabalho com IA pelo caminho.","search":"Pesquisar uma palavra…","none":"Nenhuma palavra corresponde.","close":"Fechar","count":{"one":"{count} palavra","other":"{count} palavras"},"groups":[{"id":"idea","name":"💡 Ideia e descoberta"},{"id":"plan","name":"🗺️ Planear o trabalho"},{"id":"agile","name":"🔁 Formas de trabalhar ágeis"},{"id":"build","name":"🛠️ Construir"},{"id":"test","name":"🧪 Testes e qualidade"},{"id":"change","name":"🔀 Alterar com segurança"},{"id":"run","name":"🛎️ Manter um serviço"},{"id":"sec","name":"🔒 Segurança e privacidade"},{"id":"ai","name":"🤖 Trabalhar com IA"},{"id":"money","name":"💰 Dinheiro e licenças"}],"list":[{"id":"discovery","g":"idea","word":"Descoberta (discovery)","text":"A fase inicial em que se descobre que problema vale a pena resolver e para quem, antes de se construir seja o que for.","also":["discovery","fase de descoberta","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Definição do problema","text":"Uma ou duas frases a dizer quem tem um problema, qual é e porque importa, para que todos apontem ao mesmo alvo.","also":["definições do problema","problem statement","problem statements"]},{"id":"user","g":"idea","word":"Utilizador","text":"Uma pessoa que usa aquilo que constróis. São as necessidades dela que dão sentido ao trabalho.","also":["utilizadores","user","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Parte interessada (stakeholder)","text":"Qualquer pessoa a quem importa o resultado do trabalho ou que é afetada por ele, como quem o paga, quem o usa ou quem dá apoio.","also":["partes interessadas","stakeholder","stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"Uma pessoa inventada mas realista que representa um tipo de utilizador, para a equipa poder perguntar “a Sam acharia isto fácil?”","also":["personas"]},{"id":"userresearch","g":"idea","word":"Pesquisa com utilizadores","text":"Falar com pessoas reais e observá-las para perceber o que precisam, em vez de adivinhar.","also":["entrevistas a utilizadores","user research","user interviews"]},{"id":"journey","g":"idea","word":"Jornada do utilizador","text":"Os passos que uma pessoa dá para conseguir fazer algo, desde que ouve falar disso até acabar, também fora do teu produto. Desenhá-la mostra onde ela encrava.","also":["jornadas do utilizador","jornada do cliente","user journey","customer journey"]},{"id":"painpoint","g":"idea","word":"Ponto de dor (pain point)","text":"Algo que aborrece ou atrasa as pessoas hoje. Os bons produtos tiram estes incómodos do caminho.","also":["pontos de dor","pain point","pain points"]},{"id":"assumption","g":"idea","word":"Suposição","text":"Algo em que acreditas mas que ainda não verificaste. Escrever as suposições mostra o que testar primeiro.","also":["suposições","pressuposto","pressupostos","assumption","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hipótese","text":"Um palpite que planeias verificar, com o que esperas que aconteça, como “as pessoas vão inscrever-se se o primeiro mês for grátis”.","also":["hipóteses","hypothesis","hypotheses"]},{"id":"experiment","g":"idea","word":"Experiência","text":"Um pequeno teste planeado para saber se uma ideia funciona, antes de apostares muito nela.","also":["experiências","experimento","experiment","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Prova de conceito (PoC)","text":"Uma tentativa rápida e tosca para ver se uma ideia pode funcionar. Costuma ser deitada fora assim que tens a resposta.","also":["PoC","proof of concept","prova de conceito"]},{"id":"prototype","g":"idea","word":"Protótipo","text":"Um modelo inicial do produto, muitas vezes imagens clicáveis, para testar a ideia com pessoas antes de a construir a sério.","also":["protótipos","prototype","prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe (esboço do ecrã)","text":"Um esboço simples de um ecrã que mostra onde fica cada coisa, sem cores nem conteúdo real.","also":["wireframes","esboço de ecrã","esboços"]},{"id":"mockup","g":"idea","word":"Maquete (mockup)","text":"Uma imagem detalhada do aspeto que um ecrã vai ter, com cores e textos reais, mas em que ainda nada funciona.","also":["mockup","mockups","mock-up","mock-ups","maquetes"]},{"id":"bizcase","g":"idea","word":"Caso de negócio","text":"As razões para fazer um projeto: quanto custa, o que traz ou poupa, e os riscos.","also":["casos de negócio","business case","business cases"]},{"id":"feasibility","g":"idea","word":"Viabilidade","text":"Se algo pode mesmo ser construído e mantido com o tempo, o dinheiro e as competências que tens.","also":["viável","feasibility"]},{"id":"outcome","g":"idea","word":"Resultado (outcome)","text":"A mudança que queres para as pessoas, como menos faltas às consultas. Importa mais do que a quantidade que constróis.","also":["resultados","outcome","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Entrega (output)","text":"Algo que a equipa produz, como um ecrã novo ou um relatório. Produzi-lo não quer dizer que ajude alguém.","also":["entregas","output","outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Métrica de sucesso","text":"Um número que diz se o trabalho cumpriu o seu propósito, como mais gente a concluir a encomenda.","also":["métricas de sucesso","success metric","success metrics"]},{"id":"kpi","g":"idea","word":"Indicador-chave de desempenho (KPI)","text":"Um número importante que acompanhas para ver se as coisas correm bem, como as inscrições por semana.","also":["KPI","KPIs","key performance indicator","indicadores-chave"]},{"id":"okr","g":"idea","word":"Objetivos e resultados-chave (OKR)","text":"Uma forma de definir metas: o objetivo diz o que queres e alguns resultados-chave são os números que mostram que lá chegaste.","also":["OKR","OKRs","objetivos e resultados-chave"]},{"id":"product","g":"plan","word":"Produto","text":"A coisa que é construída e mantida para os seus utilizadores, como uma aplicação, um site ou uma ferramenta.","also":["produtos","product","products"],"noTip":1},{"id":"vision","g":"plan","word":"Visão do produto","text":"Uma declaração curta sobre quem o produto ajuda e para onde vai a longo prazo.","also":["declaração de visão","product vision","vision statement"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"A pessoa que decide o que se constrói e por que ordem, para a equipa trabalhar sempre no que mais importa. No AI-gile, és tu.","also":["PO","product owners","dono do produto","responsável de produto"]},{"id":"pm","g":"plan","word":"Gestor de produto (PM)","text":"A pessoa que cuida do rumo de um produto: que problemas resolve, para quem e porquê. PM também pode querer dizer gestor de projeto, por isso confirma qual.","also":["PM","gestores de produto","product manager","product managers"]},{"id":"projmgr","g":"plan","word":"Gestor de projeto","text":"A pessoa que mantém um projeto dentro do prazo e do orçamento, a acompanhar quem faz o quê e até quando.","also":["gestores de projeto","project manager","project managers"]},{"id":"roadmap","g":"plan","word":"Roteiro (roadmap)","text":"Um plano geral do que vem nos próximos meses, por ordem. Mostra a direção e não datas exatas, e muda à medida que aprendes.","also":["roadmap","roadmaps","roteiros"]},{"id":"milestone","g":"plan","word":"Marco (milestone)","text":"Um ponto de um projeto que vale a pena assinalar, como “primeira versão no ar” ou “100 utilizadores”.","also":["marcos","milestone","milestones"]},{"id":"mvp","g":"plan","word":"Produto mínimo viável (MVP)","text":"A versão mais pequena de um produto que ainda é útil a pessoas reais, para aprenderes com elas desde cedo.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Requisito","text":"Algo que o produto final tem de fazer ou de ser.","also":["requisitos","requirement","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Âmbito (scope)","text":"O que está incluído no trabalho e, tão importante como isso, o que não está.","also":["scope","dentro do âmbito","fora do âmbito","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Derrapagem de âmbito (scope creep)","text":"Quando se vai juntando cada vez mais coisas ao trabalho, aos poucos, sem ninguém combinar o tempo ou o custo extra, e por isso nunca mais acaba.","also":["scope creep","feature creep","derrapagem de âmbito"]},{"id":"feature","g":"plan","word":"Funcionalidade (feature)","text":"Uma coisa que o produto permite às pessoas fazer, como “repor a palavra-passe”.","also":["funcionalidades","feature","features"],"noTip":1},{"id":"epic","g":"plan","word":"Épico (epic)","text":"Um trabalho grande, demasiado para fazer de uma vez, que por isso se divide em cartões mais pequenos.","also":["épicos","epic","epics"]},{"id":"story","g":"plan","word":"História de utilizador (user story)","text":"Um trabalho pequeno escrito do ponto de vista do utilizador: “Como cliente, quero guardar o meu cesto para o poder terminar mais tarde.” Serve para começar uma conversa sobre o que construir.","also":["histórias de utilizador","user story","user stories"]},{"id":"ac","g":"plan","word":"Critérios de aceitação (AC)","text":"As verificações que um cartão tem de passar para contar como concluído, combinadas antes de começar, como “o cesto continua lá depois de eu sair e voltar a entrar”.","also":["AC","critérios de aceitação","acceptance criteria"]},{"id":"task","g":"plan","word":"Tarefa","text":"Um trabalho único a fazer, muitas vezes um pequeno passo de uma história maior.","also":["tarefas","task","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket (pedido)","text":"Outra palavra para cartão: um trabalho ou um pedido, acompanhado do início ao fim.","also":["tickets","pedido","pedidos"]},{"id":"priority","g":"plan","word":"Prioridade","text":"O grau de importância ou urgência de algo em comparação com tudo o resto, para o trabalho mais importante ir primeiro.","also":["prioridades","priority","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Priorização","text":"Pôr o trabalho por ordem de importância. Uma forma comum é o MoSCoW: Must have (tem de ter), Should have (devia ter), Could have (podia ter), Won’t have (desta vez não).","also":["priorizar","prioritisation","MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimativa","text":"Um palpite sobre o tamanho ou a duração de um trabalho. É um palpite, não uma promessa.","also":["estimativas","estimar","estimate","estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Pontos de história (story points)","text":"Uma forma de adivinhar o tamanho do trabalho comparando cartões entre si (“cerca do dobro daquele”) em vez de em horas. Não servem para comparar equipas.","also":["story point","story points","pontos de esforço"]},{"id":"tshirt","g":"plan","word":"Tamanhos de T-shirt","text":"Estimar o tamanho do trabalho como S, M, L ou XL. Rápido e suficiente para planear no início.","also":["t-shirt sizing","t-shirt sizes","tamanhos S M L"]},{"id":"poker","g":"plan","word":"Planning poker","text":"Um jogo para estimar: todos mostram ao mesmo tempo uma carta com um tamanho, e depois quem escolheu o mais alto e o mais baixo explica porquê.","also":["Scrum poker","póquer de planeamento"]},{"id":"dependency","g":"plan","word":"Dependência","text":"Quando um trabalho não pode começar ou acabar enquanto outro não o fizer.","also":["dependências","dependency","dependencies"]},{"id":"blocker","g":"plan","word":"Bloqueio (blocker)","text":"Tudo o que impede o trabalho de avançar neste momento, como uma resposta que falta ou uma ferramenta avariada.","also":["bloqueios","impedimento","impedimentos","blocker","blockers"]},{"id":"deadline","g":"plan","word":"Prazo","text":"A data até à qual algo tem de estar concluído.","also":["prazos","data limite","deadline","deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Entregável","text":"Algo concreto que o trabalho produz e entrega, como uma página a funcionar ou um relatório.","also":["entregáveis","deliverable","deliverables"]},{"id":"forecast","g":"plan","word":"Previsão","text":"Uma antecipação do que é provável acontecer, como quando o trabalho estará pronto, com base no que sabes até agora.","also":["previsões","forecast","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Métrica","text":"Tudo o que medes e acompanhas ao longo do tempo, como as visitas a uma página ou o tempo que demora a corrigir um erro.","also":["métricas","metric","metrics"]},{"id":"feedback","g":"plan","word":"Feedback (retorno)","text":"O que as pessoas te dizem sobre o teu trabalho, de bom e de mau. Recebê-lo cedo e muitas vezes é o coração do Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"A lista de espera de ideias e trabalho ainda não planeados, com o mais importante no topo. Nada ali é trabalhado enquanto não passar para A fazer."},{"id":"sprint","g":"agile","word":"Sprint","text":"Um período curto e fixo de trabalho (muitas vezes uma ou duas semanas, nunca mais de um mês), com um objetivo e um conjunto combinado de cartões a concluir.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Um ponto de situação diário e rápido: o que cada elemento da equipa fez, o que faz a seguir e o que o está a travar. No Scrum chama-se reunião diária (daily scrum).","also":["standup","stand-ups","reunião diária","daily scrum","daily stand-up"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Uma forma de trabalhar em que os cartões passam pelas colunas de um quadro (como A fazer, Em curso, Concluído) e a equipa limita o que está em curso ao mesmo tempo, para o trabalho continuar a fluir."},{"id":"wip","g":"agile","word":"Limite de WIP","text":"WIP é a sigla de work in progress, trabalho em curso. Um limite de WIP é o máximo de cartões que uma coluna deve ter ao mesmo tempo, para a equipa acabar as coisas antes de começar mais.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definição de Feito","text":"A lista curta da equipa do que quer dizer “terminado”, como testado e explicado, antes de um cartão te chegar. A sua gémea, a Definição de Pronto, diz quando um cartão está claro o suficiente para começar.","also":["Definition of Ready","DoD","DoR","definição de pronto","definição de preparado"]},{"id":"retro","g":"agile","word":"Retrospetiva","text":"Um olhar regular para trás sobre como a equipa trabalha, para combinar uma ou duas coisas a fazer melhor da próxima vez. Abreviatura de retrospetiva. No AI-gile, uma retrospetiva sugere uma mudança nas formas de trabalhar da equipa, e tu dizes Avançar ou Ainda não.","also":["retro","retros","retrospetivas"]},{"id":"swarm","g":"agile","word":"Enxame","text":"Todos a ajudar: muita gente deixa o resto do trabalho para corrigir em conjunto uma única coisa urgente até estar resolvida. No AI-gile, todas as equipas ajudam num só projeto e os outros projetos esperam entretanto.","also":["swarm","swarming","modo enxame"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"No Scrum, a pessoa que ajuda a equipa a trabalhar bem: tira do caminho o que a trava, mantém as reuniões nos eixos e treina bons hábitos, sem mandar em ninguém. No AI-gile, o Lead Scrum Master deteta cartões encravados, dá um empurrão às equipas e lembra-te do que está à espera, em todos os projetos.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile (ágil)","text":"Uma forma de trabalhar em passos pequenos: constrói-se um bocadinho, mostram-se resultados reais com frequência, aprende-se com o que as pessoas dizem e muda-se o plano pelo caminho, em vez de planear tudo logo de início.","also":["ágil","desenvolvimento ágil","Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Manifesto Ágil","text":"Um texto curto escrito em 2001 por pessoas que fazem software. Põe as pessoas, os resultados que funcionam, a colaboração próxima com os clientes e a resposta à mudança à frente de planos pesados e papelada.","also":["Agile Manifesto","Manifesto for Agile Software Development","manifesto para o desenvolvimento ágil de software"]},{"id":"waterfall","g":"agile","word":"Cascata (waterfall)","text":"A forma de trabalhar mais antiga: planeia-se tudo, depois constrói-se tudo, depois testa-se tudo, uma fase após a outra. Mudar tarde é difícil e caro.","also":["waterfall","modelo em cascata","waterfall model"]},{"id":"iteration","g":"agile","word":"Iteração","text":"Uma ronda de construir algo, verificá-lo e melhorá-lo. O trabalho ágil é uma cadeia destas, e um sprint é um tipo delas.","also":["iterações","iteration","iterations"]},{"id":"increment","g":"agile","word":"Incremento","text":"Uma peça nova que funciona, acrescentada ao produto num sprint ou numa ronda de trabalho, e que encaixa no que já lá estava.","also":["incrementos","increment","increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Uma forma ágil muito popular de trabalhar: uma equipa pequena trabalha em sprints curtos rumo a um objetivo, com papéis definidos e algumas reuniões regulares para planear, verificar e melhorar."},{"id":"scrumteam","g":"agile","word":"Equipa Scrum","text":"O pequeno grupo que faz o trabalho no Scrum: um product owner, um Scrum Master e os programadores.","also":["equipas Scrum","Scrum team","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Eventos Scrum","text":"As reuniões regulares do Scrum: o planeamento do sprint, a reunião diária, a revisão do sprint e a retrospetiva. Muita gente lhes chama cerimónias.","also":["cerimónias","cerimónias Scrum","ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Planeamento do sprint","text":"A reunião no início de um sprint em que a equipa combina porque é que o sprint importa, que cartões vai assumir e como começar.","also":["reunião de planeamento","sprint planning","planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Objetivo do sprint","text":"Uma frase que diz para que serve um sprint. As tarefas pequenas podem mudar pelo caminho, desde que o objetivo seja cumprido.","also":["objetivos do sprint","sprint goal","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Backlog do sprint","text":"Os cartões escolhidos para o sprint atual, com o plano da equipa para os fazer.","also":["sprint backlog","sprint backlogs","backlogs do sprint"]},{"id":"productbacklog","g":"agile","word":"Backlog do produto","text":"A lista completa e ordenada de tudo o que pode vir a ser construído para o produto, com o mais importante no topo. Vai mudando à medida que aprendes.","also":["product backlog","product backlogs","backlogs do produto"]},{"id":"productgoal","g":"agile","word":"Objetivo do produto","text":"O resultado maior para que o produto trabalha, e que ajuda a equipa a escolher o que fazer a seguir.","also":["objetivos do produto","product goal","product goals"]},{"id":"refinement","g":"agile","word":"Refinamento do backlog","text":"Rever o backlog com regularidade para arrumar, dividir, ordenar e detalhar os cartões, de modo a ficarem prontos a pegar. Também se diz backlog grooming.","also":["refinamento","backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Revisão do sprint","text":"Uma reunião no fim de um sprint em que a equipa mostra o que concluiu e ouve o que as pessoas pensam, para decidir o que vem a seguir.","also":["revisões do sprint","sprint review","sprint reviews"]},{"id":"demo","g":"agile","word":"Demonstração (demo)","text":"Mostrar o trabalho concluído a funcionar, ao vivo, a quem o pediu.","also":["demo","demos","demonstrações"],"noTip":1},{"id":"timebox","g":"agile","word":"Limite de tempo (timebox)","text":"Uma quantidade fixa de tempo para algo. Quando acaba, paras, mesmo que nem tudo esteja feito.","also":["timebox","timeboxed","timeboxes","tempo limitado"]},{"id":"velocity","g":"agile","word":"Velocidade (velocity)","text":"A quantidade de trabalho que uma equipa costuma concluir num sprint, usada para planear quanto assumir da próxima vez. Não é uma nota ao esforço das pessoas.","also":["velocity","team velocity","velocidade da equipa"]},{"id":"capacity","g":"agile","word":"Capacidade","text":"A quantidade de trabalho que a equipa consegue assumir num período, depois de descontadas as férias e outras tarefas.","noTip":1},{"id":"burndown","g":"agile","word":"Gráfico de burndown","text":"Um gráfico do trabalho que falta num sprint a descer dia a dia. Se a linha ficar plana, há algo encravado.","also":["burndown","burn-down chart","burndown chart"]},{"id":"burnup","g":"agile","word":"Gráfico de burnup","text":"Um gráfico do trabalho concluído a subir ao longo do tempo, ao lado do total planeado, para veres quando lá chegas.","also":["burnup","burn-up chart","burnup chart"]},{"id":"kanbanboard","g":"agile","word":"Quadro Kanban","text":"O próprio quadro: uma coluna para cada fase do trabalho, com os cartões a passar de uma para outra.","also":["quadros Kanban","Kanban board","Kanban boards"]},{"id":"pullsys","g":"agile","word":"Sistema puxado (pull)","text":"Uma forma de trabalhar em que o trabalho novo só começa quando alguém tem espaço para o assumir, em vez de ser empurrado para quem já tem o prato cheio.","also":["pull system","pull-based","trabalho puxado"]},{"id":"flow","g":"agile","word":"Fluxo (flow)","text":"A fluidez com que o trabalho passa pelo quadro. Um bom fluxo quer dizer que os cartões vão andando em vez de se acumularem.","also":["flow","flow of work","fluxo de trabalho"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time (tempo total)","text":"O tempo que passa desde alguém pedir algo até estar concluído.","also":["lead times","tempo de espera total"]},{"id":"cycletime","g":"agile","word":"Cycle time (tempo de ciclo)","text":"O tempo que um cartão demora desde que o trabalho nele começa a sério até estar concluído.","also":["cycle times","tempo de ciclo"]},{"id":"throughput","g":"agile","word":"Taxa de entrega (throughput)","text":"Quantos cartões ficam concluídos por semana, ou em qualquer período definido.","also":["throughput","throughput rate","cadência de entrega"]},{"id":"bottleneck","g":"agile","word":"Gargalo (bottleneck)","text":"A fase única onde o trabalho se acumula e atrasa tudo o que vem atrás, como o gargalo estreito de uma garrafa.","also":["bottleneck","bottlenecks","estrangulamento","afunilamento"]},{"id":"swimlane","g":"agile","word":"Pista (swimlane)","text":"Uma linha que atravessa o quadro e agrupa cartões de um mesmo tipo, como o trabalho urgente ou os cartões de uma equipa.","also":["swimlane","swimlanes","swim lane","pistas"]},{"id":"lean","g":"agile","word":"Lean","text":"Uma forma de trabalhar que corta o desperdício (tudo o que não ajuda o cliente) e mantém o trabalho a fluir."},{"id":"waste","g":"agile","word":"Desperdício (waste)","text":"No Lean, tudo o que dá trabalho mas não ajuda o cliente, como esperas, refazer coisas ou construir o que ninguém usa.","noTip":1},{"id":"kaizen","g":"agile","word":"Melhoria contínua","text":"Ir melhorando um pouco a toda a hora com pequenas mudanças regulares, e verificar depois se ajudaram. As retrospetivas são uma maneira de o fazer. Também se diz kaizen.","also":["kaizen","continuous improvement"]},{"id":"selforg","g":"agile","word":"Equipa auto-organizada","text":"Uma equipa que decide por si como fazer o trabalho, em vez de lhe dizerem passo a passo.","also":["auto-organizada","equipa autogerida","self-organising","self-organizing","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Equipa multidisciplinar","text":"Uma equipa que tem todas as competências de que precisa para acabar o trabalho sozinha, como desenho, construção e testes.","also":["multidisciplinar","equipa multifuncional","cross-functional"]},{"id":"spike","g":"agile","word":"Spike (estudo rápido)","text":"Uma pesquisa curta e com tempo limitado para responder a uma pergunta antes de assumir o trabalho a sério.","also":["spikes","estudo rápido"]},{"id":"rework","g":"agile","word":"Retrabalho","text":"Fazer o trabalho outra vez porque não ficou certo à primeira.","also":["refazer","rework","reworked"]},{"id":"safe","g":"agile","word":"Agile em escala (SAFe)","text":"Formas de usar o Agile em muitas equipas de uma grande organização. O SAFe (Scaled Agile Framework) é um exemplo bem conhecido.","also":["scaled Agile","Agile à escala"]},{"id":"repo","g":"build","word":"Repo","text":"A pasta de código do projeto com todo o histórico de commits. Pode estar no teu computador, no GitHub, ou nos dois.","also":["repositório","repository"]},{"id":"branch","g":"build","word":"Branch","text":"Uma linha de trabalho separada no código, para fazer alterações sem tocar na versão principal.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Um instantâneo guardado do código, com uma nota curta do que mudou. Podes sempre voltar a um deles.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Enviar as tuas versões guardadas (commits) deste computador para a cópia partilhada online, como o GitHub, para ficarem com cópia de segurança e outros as poderem obter."},{"id":"merge","g":"build","word":"Merge","text":"Juntar as alterações de um ramo noutro, normalmente de volta à versão principal."},{"id":"pr","g":"build","word":"Pull request","text":"Pedir que as alterações de um ramo sejam verificadas e juntas à versão principal. Alguns sites chamam-lhe merge request.","also":["PR","PRs","pull request","merge request","pedido de integração"]},{"id":"refactor","g":"build","word":"Refactor","text":"Arrumar o código sem mudar o que ele faz: ficheiros mais pequenos, nomes mais claros, menos repetição."},{"id":"bug","g":"build","word":"Bug","text":"Algo que não funciona como devia.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Revisão por pares","text":"Um segundo par de olhos: alguém que não é o autor verifica o trabalho antes de chegar a ti, para passarem menos erros. No AI-gile, outra IA verifica cada cartão.","also":["revisão de código","code review","peer review"]},{"id":"code","g":"build","word":"Código","text":"As instruções escritas que dizem a um computador o que fazer. Também se diz código-fonte.","also":["código-fonte","code","source code"],"noTip":1},{"id":"proglang","g":"build","word":"Linguagem de programação","text":"Uma linguagem para escrever código, como JavaScript, Python ou Java. Cada uma serve melhor para certos trabalhos.","also":["linguagens de programação","programming language","programming languages"]},{"id":"developer","g":"build","word":"Programador (dev)","text":"Quem escreve e altera código. Também se diz programador ou engenheiro de software.","also":["programador","programadores","developer","developers","dev","devs","engenheiro de software","programmer","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Os programas que correm em computadores e telemóveis, por oposição às próprias máquinas (o hardware).","noTip":1},{"id":"app","g":"build","word":"Aplicação (app)","text":"Abreviatura de aplicação: um programa que as pessoas usam para fazer algo, no telemóvel, no computador ou num navegador.","also":["app","apps","aplicações","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Aplicação web","text":"Uma aplicação que corre num navegador, por isso não há nada para instalar.","also":["aplicações web","web app","web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"A parte de uma aplicação que vês e em que clicas: os ecrãs, os botões e as palavras, muitas vezes no teu navegador.","also":["front-end","frontend","parte visível"]},{"id":"backend","g":"build","word":"Back end","text":"A parte de uma aplicação que trabalha nos bastidores, guarda os dados e faz o trabalho quando clicas em algo, como verificar a tua palavra-passe.","also":["back-end","backend","parte invisível"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Trabalhar tanto no front end como no back end.","also":["full-stack","completo"]},{"id":"ui","g":"build","word":"Interface de utilizador (UI)","text":"Aquilo que uma pessoa vê e usa no ecrã: a disposição, os botões, os menus e os textos.","also":["UI","interface","user interface"]},{"id":"ux","g":"build","word":"Experiência de utilizador (UX)","text":"Como é usar algo: fácil, claro e agradável, ou confuso e lento.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Acessibilidade (a11y)","text":"Fazer com que as coisas possam ser usadas por todos, incluindo quem vê mal, quem não consegue usar um rato ou quem usa um leitor de ecrã.","also":["a11y","acessível"]},{"id":"responsive","g":"build","word":"Design adaptável (responsive)","text":"Fazer com que as páginas se ajustem e funcionem bem em qualquer tamanho de ecrã, do telemóvel ao monitor grande.","also":["design responsivo","adaptável"]},{"id":"designsys","g":"build","word":"Sistema de design","text":"Um conjunto partilhado de cores, tipos de letra, botões e regras, para que todos os ecrãs tenham o mesmo aspeto e o mesmo comportamento.","also":["sistemas de design","design system","design systems"]},{"id":"architecture","g":"build","word":"Arquitetura","text":"A forma geral de um sistema: quais são as partes principais e como falam umas com as outras."},{"id":"database","g":"build","word":"Base de dados (BD)","text":"Um sítio organizado para guardar informação, como uma folha de cálculo muito potente que a aplicação pode ler e alterar.","also":["bases de dados","BD","database","databases","DB"]},{"id":"schema","g":"build","word":"Esquema da base de dados","text":"A estrutura de uma base de dados: que tabelas de informação tem e o que vai em cada uma.","also":["esquema","schema"]},{"id":"sql","g":"build","word":"SQL","text":"Sigla de “linguagem de consulta estruturada”: a linguagem usada para pedir informação a muitas bases de dados ou para a alterar.","also":["Structured Query Language","linguagem de consulta estruturada"]},{"id":"data","g":"build","word":"Dados","text":"Informação guardada por um computador, como nomes, encomendas ou definições.","also":["conjunto de dados","conjuntos de dados","data","dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Servidor","text":"Um computador sempre ligado que responde a pedidos de outros computadores, como enviar-te uma página web quando a visitas.","also":["servidores","server","servers"]},{"id":"client","g":"build","word":"Cliente (client)","text":"O lado que pede algo, normalmente o teu navegador ou aplicação, a falar com um servidor. Nos negócios, também quer dizer apenas quem compra.","also":["clientes","client","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Sigla de “interface de programação de aplicações”: um menu de pedidos que um programa pode fazer a outro, como pedir a um serviço de meteorologia a previsão de hoje.","also":["APIs","interface de programação de aplicações","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint (ponto de acesso)","text":"Um item do menu de uma API: um endereço web que um programa pode chamar para obter ou enviar algo.","also":["endpoints","ponto de acesso","pontos de acesso"]},{"id":"integration","g":"build","word":"Integração","text":"Ligar dois sistemas para que trabalhem juntos, como a tua loja enviar as encomendas para o programa de contabilidade.","also":["integrações","integration","integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"Uma mensagem que um sistema envia a outro por si próprio no momento em que algo acontece, como “pagamento recebido”.","also":["webhooks"]},{"id":"library","g":"build","word":"Biblioteca (library)","text":"Código já feito por outra pessoa que podes reutilizar em vez de o escreveres tu.","also":["bibliotecas","library","libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework (estrutura base)","text":"Uma estrutura já pronta para construir uma aplicação, que decide grande parte de como o código se organiza, como a armação de uma casa que depois preenches.","also":["frameworks","estrutura base"]},{"id":"sdk","g":"build","word":"Kit de desenvolvimento de software (SDK)","text":"Uma caixa de ferramentas, código e exemplos para criar software para uma plataforma ou serviço.","also":["SDK","SDKs","software development kit"]},{"id":"softdep","g":"build","word":"Dependência de software","text":"Uma biblioteca ou ferramenta de que o teu código precisa para funcionar. Mantê-las atualizadas é importante para a segurança.","also":["dependências de software","software dependency","software dependencies"]},{"id":"package","g":"build","word":"Pacote","text":"Um conjunto de código já feito que podes instalar e usar num projeto.","also":["pacotes","package","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Gestor de pacotes","text":"Uma ferramenta que vai buscar e atualiza os pacotes de que o teu código depende. O npm é um dos mais comuns.","also":["gestores de pacotes","package manager","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"A ferramenta mais usada para guardar o histórico das alterações ao código, em commits e ramos (branches)."},{"id":"github","g":"build","word":"GitHub","text":"Um site que guarda repositórios Git online, para as equipas partilharem código, reverem alterações e acompanharem o trabalho."},{"id":"vcs","g":"build","word":"Controlo de versões","text":"Guardar o histórico completo de todas as alterações aos ficheiros, para veres quem mudou o quê e poderes voltar atrás se for preciso. O Git faz isto.","also":["controlo de versão","sistema de controlo de versões","version control","source control","version control system"]},{"id":"clone","g":"build","word":"Clonar (clone)","text":"Fazer a tua própria cópia completa de um repositório, com o histórico, no teu computador.","also":["clone","clonar","cloned","cloning"]},{"id":"pull","g":"build","word":"Pull (puxar)","text":"Ir buscar os commits mais recentes à cópia partilhada (como o GitHub) para o teu computador. O contrário de push.","also":["git pull","puxar"],"noTip":1},{"id":"mainbranch","g":"build","word":"Ramo principal (main)","text":"A versão oficial do código a partir da qual todos trabalham, muitas vezes chamada main ou master.","also":["main","master","ramo master","master branch"]},{"id":"conflict","g":"build","word":"Conflito de merge","text":"Quando duas alterações mexem nas mesmas linhas de maneiras diferentes, e o computador não as consegue juntar, por isso uma pessoa tem de escolher.","also":["conflitos de merge","merge conflict","merge conflicts"]},{"id":"diff","g":"build","word":"Diff (diferenças)","text":"Uma vista que mostra exatamente o que mudou entre duas versões: linhas acrescentadas e linhas retiradas.","also":["diffs","diferenças"]},{"id":"fork","g":"build","word":"Fork (bifurcação)","text":"A tua própria cópia do repositório de outra pessoa, que podes alterar sem afetar o original.","also":["forks","forked","bifurcação"]},{"id":"script","g":"build","word":"Script","text":"Um programa curto que faz uma tarefa sozinho, como arrumar ficheiros ou arrancar a aplicação.","also":["scripts","guião"],"noTip":1},{"id":"build","g":"build","word":"Build (compilação)","text":"Transformar o código em algo pronto a correr, ou o próprio resultado pronto a correr.","also":["builds","compilação"],"noTip":1},{"id":"compile","g":"build","word":"Compilar","text":"Traduzir o código que as pessoas escreveram para uma forma que o computador consegue executar diretamente.","also":["compile","compilado","compilador","compiler"]},{"id":"cli","g":"build","word":"Linha de comandos (CLI)","text":"Uma janela de texto onde escreves instruções para o computador em vez de clicares. Também se chama terminal.","also":["linha de comandos","command line","command-line","CLI","terminal","consola"]},{"id":"config","g":"build","word":"Configuração (config)","text":"As definições que controlam o comportamento do software, guardadas à parte do código para serem fáceis de mudar.","also":["config","configuração","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Variável de ambiente","text":"Uma definição entregue a um programa quando arranca, muitas vezes usada para endereços ou palavras-passe, para não ficarem escritos no código.","also":["variáveis de ambiente","environment variable","environment variables","env var"]},{"id":"debugging","g":"build","word":"Depuração (debugging)","text":"Descobrir porque é que algo não funciona e corrigi-lo.","also":["depurar","debug","debugged","debugging"]},{"id":"pairing","g":"build","word":"Programação em par","text":"Duas pessoas (ou uma pessoa e uma IA) a trabalhar juntas no mesmo código, uma a escrever e outra a verificar.","also":["pair programming","pairing","programar em par"]},{"id":"docs","g":"build","word":"Documentação (docs)","text":"Explicações escritas sobre como algo funciona ou como se usa.","also":["documentação","docs","documentation"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"O primeiro ficheiro a ler num repositório: o que é o projeto e como pô-lo a funcionar.","also":["READMEs","leia-me"]},{"id":"legacy","g":"build","word":"Sistema legado (legacy)","text":"Um sistema antigo que ainda está em uso e é difícil de mudar, muitas vezes porque poucas pessoas ainda o entendem.","also":["sistemas legados","código legado","legacy","legacy system","legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Dívida técnica","text":"Atalhos que poupam tempo agora mas tornam as alterações futuras mais lentas, como um empréstimo que vai acumulando juros. Refatorar é pagá-la aos poucos.","also":["dívida técnica","tech debt","technical debt"]},{"id":"test","g":"test","word":"Teste","text":"Uma verificação de que algo funciona como deve. Alguns testes são feitos pelo computador sozinho sempre que o código muda; outros és tu a experimentar um cartão concluído antes de o aceitares.","also":["testes","testar","testares"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Sigla de “garantia de qualidade” (quality assurance): tudo o que se faz para garantir que o trabalho está certo antes de ir para o ar. No AI-gile quer dizer as verificações automáticas: quando o QA está vermelho, algo falhou e não pode ir para o ar enquanto não for corrigido.","also":["garantia de qualidade","verificações de qualidade"]},{"id":"testpile","g":"test","word":"Pilha de testes","text":"Os cartões terminados à espera que os experimentes, um a seguir ao outro. Aceita um ou devolve-o com uma nota, e aparece o seguinte.","also":["pilhas de testes","test pile"]},{"id":"autotest","g":"test","word":"Teste automático","text":"Uma verificação que o computador faz sozinho sempre que o código muda, para apanhar erros cedo.","also":["testes automáticos","testes automatizados","automated test","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Teste manual","text":"Uma pessoa a experimentar o trabalho à mão para ver se se comporta como deve.","also":["testes manuais","manual test","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Teste unitário","text":"Uma pequena verificação automática de um pedacinho de código, isolado.","also":["testes unitários","unit test","unit tests"]},{"id":"integtest","g":"test","word":"Teste de integração","text":"Uma verificação de que várias partes funcionam bem em conjunto, e não apenas uma de cada vez.","also":["testes de integração","integration test","integration tests"]},{"id":"endtoend","g":"test","word":"Teste de ponta a ponta (E2E)","text":"Um teste que age como um utilizador real do princípio ao fim, por exemplo inscrever-se, comprar e pagar.","also":["E2E","end-to-end tests","testes de ponta a ponta"]},{"id":"uat","g":"test","word":"Teste de aceitação (UAT)","text":"As pessoas que pediram o trabalho experimentam-no elas próprias e dizem se faz o que precisam. A pilha de testes do AI-gile é a sua versão disto.","also":["UAT","acceptance testing","user acceptance testing","testes de aceitação"]},{"id":"regression","g":"test","word":"Regressão","text":"Algo que funcionava e deixou de funcionar depois de uma alteração. Os testes de regressão verificam que o que já existia continua a funcionar.","also":["regressões","teste de regressão","testes de regressão","regression","regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Teste de fumo (smoke test)","text":"Uma verificação muito rápida de que as coisas principais funcionam, por exemplo logo depois de uma alteração entrar no ar. Se falhar, interrompe e vai ver o que se passa.","also":["smoke test","smoke tests","testes de fumo"]},{"id":"exploratory","g":"test","word":"Teste exploratório","text":"Experimentar o produto à vontade e mexer-lhe de várias maneiras, para encontrar problemas que as verificações planeadas não apanhariam.","also":["testes exploratórios","exploratory test","exploratory tests","exploratory testing"]},{"id":"testcase","g":"test","word":"Caso de teste","text":"Um cenário escrito para experimentar: os passos e o que deve acontecer.","also":["casos de teste","test case","test cases"]},{"id":"coverage","g":"test","word":"Cobertura de testes","text":"Quanto do código é verificado por testes automáticos. Mais costuma ser mais seguro, mas uma cobertura alta, por si só, não prova que funciona bem.","also":["cobertura","cobertura de código","code coverage","test coverage"]},{"id":"testdata","g":"test","word":"Dados de teste","text":"Informação de exemplo inventada, usada durante os testes, para não expor dados privados de pessoas reais.","also":["test fixtures","test data"]},{"id":"edgecase","g":"test","word":"Caso limite (edge case)","text":"Uma situação invulgar nos limites, como um formulário vazio ou um nome com apóstrofo, onde as coisas costumam partir-se.","also":["casos limite","edge case","edge cases","caso extremo"]},{"id":"happypath","g":"test","word":"Caminho feliz (happy path)","text":"O percurso normal em que tudo corre bem. Um bom teste experimenta também os caminhos infelizes."},{"id":"perftest","g":"test","word":"Teste de desempenho","text":"Verificar a rapidez de algo e como aguenta quando está sob pressão.","also":["testes de desempenho","performance test","performance tests","performance testing"]},{"id":"loadtest","g":"test","word":"Teste de carga","text":"Verificar como um sistema se aguenta quando muita gente o usa ao mesmo tempo.","also":["testes de carga","load test","load tests","load testing"]},{"id":"sectest","g":"test","word":"Teste de segurança","text":"Procurar fraquezas que possam deixar alguém usar mal um sistema ou ver o que não devia.","also":["testes de segurança","security test","security tests","security testing"]},{"id":"accesstest","g":"test","word":"Teste de acessibilidade","text":"Verificar se pessoas com capacidades diferentes conseguem usar o produto, incluindo com um leitor de ecrã ou só com o teclado.","also":["testes de acessibilidade","accessibility test","accessibility testing"]},{"id":"linting","g":"test","word":"Linting (análise de estilo)","text":"Uma verificação automática que deteta prováveis erros e um estilo desarrumado no código, como um corretor ortográfico para programas.","also":["linter","lint","linting"]},{"id":"static","g":"test","word":"Análise estática","text":"Procurar problemas no código lendo-o automaticamente, sem o executar.","also":["análise estática de código","static analysis","static code analysis"]},{"id":"flaky","g":"test","word":"Teste instável (flaky)","text":"Um teste que umas vezes passa e outras falha sem motivo claro, por isso não merece confiança total.","also":["testes instáveis","flaky test","flaky tests","flaky"]},{"id":"repro","g":"test","word":"Reproduzir (repro)","text":"Fazer um erro acontecer de novo de propósito, seguindo os mesmos passos, para o poder estudar e corrigir. Escrever esses passos é a parte mais útil de um relatório de erro.","also":["repro","reproduzir","reproduce","passos para reproduzir","steps to reproduce"]},{"id":"severity","g":"test","word":"Gravidade","text":"O quão mau é o efeito de um problema, de um pequeno incómodo até tudo parar.","also":["nível de gravidade","severity","severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Copiar uma versão nova do software para os computadores que o fazem funcionar, como uma cópia de teste ou o serviço no ar."},{"id":"release","g":"change","word":"Lançamento","text":"Um pacote de trabalho terminado, com nome, que vai para o ar de uma vez, com notas curtas sobre o que mudou. 🚀 Lançamentos escreve as notas a partir dos cartões feitos.","also":["lançamentos","release","releases"]},{"id":"rollback","g":"change","word":"Rollback","text":"Voltar à última versão que funcionava quando uma nova dá problemas. No AI-gile, Reverter junta numa única lista de verificação os passos de anulação escritos em cada alteração.","also":["reverter","reversão","voltar atrás"]},{"id":"live","g":"change","word":"Em produção","text":"A versão verdadeira que as pessoas usam, ao contrário de uma cópia para experimentar coisas. Os programadores chamam-lhe produção.","also":["produção","no ar","live"],"noTip":1},{"id":"change","g":"change","word":"Alteração","text":"Uma alteração planeada a algo de que as pessoas dependem, escrita primeiro: o quê, porquê, o risco, quando e como desfazer. Começa uma com 🔀 Propor uma alteração.","also":["alterações","pedido de alteração","mudança","change request"],"noTip":1},{"id":"risk","g":"change","word":"Risco","text":"Algo que pode correr mal, pontuado pela probabilidade e pela gravidade. ⚠️ Riscos guarda-os numa só lista, da pontuação mais alta para a mais baixa, cada um com uma data para voltar a olhar.","also":["riscos","registo de riscos"]},{"id":"chgwin","g":"change","word":"Janela de alterações","text":"As horas em que as alterações podem ir para o ar, como uma terça-feira à noite sossegada. Fora de uma janela, um cartão de alteração não pode ser terminado, a não ser que seja uma emergência.","also":["janelas de alterações","change window"]},{"id":"gonogo","g":"change","word":"Avançar / não avançar","text":"Uma última verificação mesmo antes de uma alteração ir para o ar: cada pessoa que tem de aprovar diz Avançar ou Não avançar. Só segue quando todos dizem Avançar.","also":["go/no go","go-no-go","go / no go"]},{"id":"approval","g":"change","word":"Aprovação","text":"Esperar por um sim antes de o trabalho começar. Um cartão aberto por um amigo, ou uma alteração, espera em ✅ Aprovações até o aprovares ou recusares.","also":["aprovações"]},{"id":"quiettime","g":"change","word":"Hora de silêncio","text":"Um período, como durante uma transmissão em direto, uma demonstração ou de noite, em que nada vai para o ar. As equipas continuam a trabalhar e a testar, mas a publicação espera até acabar. Noutros sítios chama-se congelamento de alterações (change freeze).","also":["horas de silêncio","congelamento de alterações","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Uma forma de trabalhar em que quem constrói o software e quem o põe a funcionar formam uma só equipa, com muita automatização, para as alterações irem para o ar com frequência e em segurança."},{"id":"cicd","g":"change","word":"CI/CD (integração e entrega contínuas)","text":"As alterações de todos são juntadas à versão principal com frequência e verificadas automaticamente de cada vez (integração contínua), para o software estar sempre pronto a ir para o ar com o carregar de um botão (entrega contínua).","also":["CI/CD","CI","CD","integração contínua","entrega contínua","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Implementação contínua (continuous deployment)","text":"Um passo além da entrega contínua: cada alteração que passa nas verificações vai para o ar sozinha, sem botão para carregar.","also":["implementação contínua","continuous deployment","continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline (cadeia automática)","text":"A série automática de passos por que uma alteração passa a caminho do ar, como compilar, testar e depois publicar.","also":["pipelines","cadeia automática"]},{"id":"environment","g":"change","word":"Ambiente","text":"Uma cópia separada do sistema para um fim, como uma para construir, outra para testar e a que está no ar.","also":["ambientes","environment","environments"],"noTip":1},{"id":"devenv","g":"change","word":"Ambiente de desenvolvimento","text":"A cópia em que um programador trabalha, muitas vezes no seu próprio computador, onde estragar coisas não prejudica ninguém.","also":["ambiente de dev","dev environment","development environment"]},{"id":"testenv","g":"change","word":"Ambiente de teste","text":"Uma cópia separada do sistema usada só para testar, para não tocar no serviço verdadeiro.","also":["ambientes de teste","test environment","test environments"]},{"id":"staging","g":"change","word":"Ambiente de pré-produção (staging)","text":"Uma última cópia montada igual à que está no ar, para uma verificação final antes de uma alteração ir para o ar.","also":["staging","pré-produção","staging environment"]},{"id":"artifact","g":"change","word":"Artefacto de build","text":"O ficheiro ou pacote que uma build produz, pronto a ser guardado, verificado ou posto no ar.","also":["artefactos de build","build artifact","build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix (correção urgente)","text":"Uma correção urgente posta no ar depressa, fora do plano normal, porque algo importante está avariado.","also":["hotfixes","correção urgente"]},{"id":"patch","g":"change","word":"Patch (atualização corretiva)","text":"Uma pequena atualização que corrige um erro ou fecha uma falha de segurança. Aplicar depressa as atualizações de segurança é importante.","also":["patches","patch de segurança","atualização de segurança","security patch","security patches"]},{"id":"version","g":"change","word":"Número de versão","text":"Uma etiqueta como 2.4.1 que diz que versão tens. Muitas vezes o primeiro número muda nas mudanças grandes e o último nas pequenas correções.","also":["números de versão","versionamento semântico","version number","version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Notas de lançamento","text":"Uma lista curta e simples do que mudou numa versão, para quem a usa, incluindo correções e limites conhecidos. Também se diz changelog.","also":["notas da versão","changelog","change log","registo de alterações"]},{"id":"flag","g":"change","word":"Feature flag (interruptor de funcionalidade)","text":"Um interruptor de ligar e desligar para uma funcionalidade, para o trabalho novo ir para o ar escondido e ser ligado (ou desligado outra vez) sem uma nova versão.","also":["feature flags","feature toggle","feature toggles","interruptor de funcionalidade"]},{"id":"rollfwd","g":"change","word":"Corrigir em frente (roll forward)","text":"Corrigir uma versão má lançando depressa uma versão nova e corrigida, em vez de voltar à antiga.","also":["roll forward","rolling forward","rolled forward","avançar a correção"]},{"id":"canary","g":"change","word":"Lançamento canário (canary)","text":"Pôr uma alteração no ar primeiro para um grupo pequeno, e para todos só quando parecer estar bem. O nome vem dos canários que os mineiros levavam para o subsolo como aviso antecipado.","also":["canary","canary release","canary releases","lançamento canário"]},{"id":"bluegreen","g":"change","word":"Implementação blue-green","text":"Manter duas cópias do sistema no ar e passar as pessoas para a nova de uma só vez, para poder voltar logo atrás se algo correr mal.","also":["blue-green","blue green deployment","blue-green deployment"]},{"id":"zerodown","g":"change","word":"Implementação sem paragem","text":"Pôr uma versão nova no ar sem o serviço alguma vez parar para os utilizadores.","also":["zero downtime","zero-downtime","sem tempo de inatividade"]},{"id":"chgenable","g":"change","word":"Gestão de mudanças","text":"Ajudar as mudanças a correr bem: avaliar o risco, obter a aprovação certa e escolher um bom momento. Também se diz change management.","also":["change enablement","change management","gestão da mudança"]},{"id":"cab","g":"change","word":"Comité consultivo de mudanças (CAB)","text":"Um grupo que analisa as mudanças importantes e decide se e quando podem avançar.","also":["CAB","change advisory board"]},{"id":"stdchange","g":"change","word":"Mudança padrão","text":"Uma mudança de baixo risco, feita sempre da mesma maneira testada, por isso aprovada de antemão.","also":["mudanças padrão","standard change","standard changes"]},{"id":"normchange","g":"change","word":"Mudança normal","text":"Uma mudança que tem de ser verificada e aprovada antes de avançar.","also":["mudanças normais","normal change","normal changes"]},{"id":"emergchange","g":"change","word":"Mudança de emergência","text":"Uma mudança que tem de acontecer já para corrigir ou evitar um problema grave, com uma aprovação mais rápida em conformidade.","also":["mudanças de emergência","emergency change","emergency changes"]},{"id":"automation","g":"change","word":"Automatização","text":"Pôr o computador a fazer sozinho uma tarefa repetida, para ser mais rápida e feita sempre da mesma maneira.","also":["automação","automatizado","automated"],"noTip":1},{"id":"infra","g":"change","word":"Infraestrutura","text":"As máquinas, as redes e os serviços em que o software corre.","also":["infra","infraestruturas"]},{"id":"iac","g":"change","word":"Infraestrutura como código (IaC)","text":"Descrever os teus servidores e definições em ficheiros guardados com o código, para poderem ser refeitos exatamente da mesma maneira sempre que for preciso.","also":["IaC","infrastructure as code"]},{"id":"cloud","g":"change","word":"Nuvem (cloud)","text":"Alugar computadores, armazenamento e serviços a um grande fornecedor pela internet, em vez de teres tu as máquinas.","also":["cloud","a nuvem","computação em nuvem","the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Fornecedor de nuvem","text":"Uma empresa que aluga capacidade de computação pela internet, como a Amazon Web Services (AWS), a Microsoft Azure ou a Google Cloud.","also":["fornecedores de nuvem","cloud provider","cloud providers"]},{"id":"hosting","g":"change","word":"Alojamento (hosting)","text":"Onde a tua aplicação ou site vive e funciona para as pessoas lá chegarem, normalmente alugado a uma empresa.","also":["hosting","hospedagem","alojado"]},{"id":"domain","g":"change","word":"Nome de domínio","text":"O endereço web que as pessoas escrevem, como exemplo.com. Alugas por ano, por isso tem de ser renovado.","also":["nomes de domínio","domínio","domain","domain name","domain names"]},{"id":"dns","g":"change","word":"DNS","text":"Sigla de “sistema de nomes de domínio”: o livro de endereços da internet, que transforma um nome como exemplo.com no endereço do computador certo.","also":["sistema de nomes de domínio","domain name system"]},{"id":"container","g":"change","word":"Contentor (container)","text":"Um pacote selado com uma aplicação e tudo o que ela precisa, para correr da mesma maneira em qualquer computador. O Docker é a ferramenta mais conhecida.","also":["contentores","container","containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Máquina virtual (VM)","text":"Um computador de faz de conta a correr dentro de um real, para uma máquina grande poder funcionar como muitas.","also":["VM","VMs","máquinas virtuais","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless (sem servidores)","text":"Correr código sem cuidares de servidor nenhum: o fornecedor corre-o quando é preciso e pagas só o que usas."},{"id":"lb","g":"change","word":"Balanceador de carga","text":"Algo que reparte os visitantes por vários servidores, para nenhum ficar sobrecarregado.","also":["balanceadores de carga","load balancer","load balancers"]},{"id":"cache","g":"change","word":"Cache (memória rápida)","text":"Um depósito à mão de resultados recentes, para não ser preciso ir buscar ou calcular a mesma coisa outra vez. Limpá-la pode resolver páginas que parecem desatualizadas.","also":["caches","memória rápida","caching","cached"]},{"id":"cdn","g":"change","word":"Rede de distribuição de conteúdos (CDN)","text":"Um conjunto mundial de servidores com cópias das tuas páginas e imagens perto dos visitantes, para carregarem depressa.","also":["CDN","content delivery network"]},{"id":"migration","g":"change","word":"Migração","text":"Passar dados ou sistemas de uma configuração antiga para uma nova, ou mudar com cuidado a estrutura de uma base de dados.","also":["migrações","migração de base de dados","migration","migrations","database migration"]},{"id":"service","g":"run","word":"Serviço","text":"Algo que construíste e de que as pessoas dependem, como um site ou uma app, cuidado para continuar a funcionar. Marca “Este projeto é um serviço” e diz o que oferece, quem o usa e quem está de prevenção.","also":["serviços"]},{"id":"uptimepct","g":"run","word":"Tempo de funcionamento (uptime)","text":"A parte do tempo em que um serviço está a funcionar, normalmente em percentagem. Com 99,9% ainda são permitidos cerca de 43 minutos parado por mês.","also":["uptime","percentagem de uptime","uptime percentage"]},{"id":"uptime","g":"run","word":"Verificação de disponibilidade","text":"Uma verificação automática, de poucos em poucos minutos, de que o teu serviço ainda responde. Se falhar várias vezes seguidas, o AI-gile abre sozinho um cartão de incidente.","also":["verificações de disponibilidade","uptime checks"]},{"id":"statuspage","g":"run","word":"Página de estado","text":"Uma página pública que mostra se um serviço está a funcionar (verde, laranja ou vermelho), com a última atualização, para quem o usa poder ver em vez de perguntar.","also":["páginas de estado","página de status","status page"]},{"id":"desk","g":"run","word":"Service desk","text":"Onde chegam as perguntas e os relatos das pessoas que usam o teu serviço. O AI-gile classifica cada um como pedido, incidente ou ideia, e avisa quando parece algo que já foi relatado.","also":["service desks","secretária","balcão de atendimento","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Pedido de serviço","text":"Alguém a pedir algo normal, como uma conta nova ou uma pequena ajuda, em vez de avisar que algo está avariado. Espera pela sua vez; um incidente passa à frente.","also":["pedidos de serviço","pedido"]},{"id":"incident","g":"run","word":"Incidente","text":"Algo que está avariado ou a não funcionar bem para quem o está a usar neste momento, como o site em baixo ou muito lento. Um cartão de incidente 🔥 passa à frente da fila: pô-lo a funcionar outra vez vem primeiro.","also":["incidentes","avaria","em baixo"]},{"id":"major","g":"run","word":"Incidente grave","text":"Um incidente grande: muitas pessoas afetadas, ou dinheiro ou dados em risco. Um botão põe todas as equipas nele (enxame), acorda quem está de prevenção e pede uma atualização de estado a cada 30 minutos.","also":["incidentes graves","major incident"]},{"id":"oncall","g":"run","word":"De prevenção","text":"Ser quem responde quando algo avaria, mesmo à noite. Cada serviço tem um membro da equipa de prevenção, que é acordado primeiro nos incidentes desse serviço.","also":["prevenção","on call","on-call","piquete"]},{"id":"replyby","g":"run","word":"Prazo de resposta","text":"Quanto tempo um cartão pode esperar por uma primeira resposta, por exemplo uma hora para um incidente. Depois disso ganha um relógio vermelho, para nada ficar esquecido em silêncio. Também se chama objetivo de resposta.","also":["prazos de resposta","objetivo de resposta","tempo de resposta"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Um olhar rápido para trás depois de um incidente: o que aconteceu, o que ajudou e o que mudar, sem culpar ninguém. Um incidente não pode ser fechado sem um.","also":["post-mortems","postmortem","revisão pós-incidente"]},{"id":"problem","g":"run","word":"Problema","text":"A causa escondida por trás de um ou mais incidentes. Um cartão de 🧩 problema junta incidentes que continuam a voltar, para a causa ser encontrada e corrigida de vez.","also":["problemas"],"noTip":1},{"id":"rootcause","g":"run","word":"Causa raiz","text":"A verdadeira razão de algo ter avariado, não só o que se viu a correr mal. Corrige a causa raiz e o incidente deixa de voltar.","also":["causas raiz","root cause"]},{"id":"workaround","g":"run","word":"Solução provisória","text":"Uma forma de manter as coisas a funcionar até a correção verdadeira estar pronta, como reiniciar algo quando bloqueia. Fica escrita no cartão do problema, para ninguém ter de a descobrir outra vez.","also":["soluções provisórias","workaround","contorno"]},{"id":"knownerror","g":"run","word":"Erro conhecido","text":"Um problema cuja causa é conhecida mas que ainda não está corrigido, normalmente com uma solução provisória escrita. Os 🧩 Erros conhecidos listam-nos, para todos usarem a solução provisória em vez de investigar outra vez.","also":["erros conhecidos","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Instruções passo a passo para resolver um tipo de problema conhecido, para ser feito da mesma maneira, depressa, todas as vezes. Depois de um incidente grande, a equipa pode propor um para lhe dares o OK.","also":["runbooks","manual de procedimentos","guião"]},{"id":"ci","g":"run","word":"Item de configuração","text":"Uma coisa de que o teu serviço depende, como um servidor, um domínio, um certificado, uma chave ou um fornecedor. 🗂️ Itens de configuração lista-os por serviço, para veres o que um incidente afeta e o que precisa de ser renovado ou de ter cópia de segurança.","also":["itens de configuração"]},{"id":"expiry","g":"run","word":"Data de validade","text":"A data em que algo deixa de funcionar se não for renovado, como o certificado de segurança de um site ou o seu endereço web. O AI-gile vigia estas datas e cria um cartão para renovar cada uma 30 dias antes, para nada parar de surpresa.","also":["datas de validade","validade","expiração","vigilância de validade"]},{"id":"backup","g":"run","word":"Cópia de segurança","text":"Uma cópia guardada dos teus dados de antes, para recorrer se algo se perder ou estragar. O AI-gile faz todos os dias uma cópia de segurança dos teus quadros.","also":["cópias de segurança","backup","backups"]},{"id":"restore","g":"run","word":"Restauro","text":"Repor os dados a partir de uma cópia de segurança. Uma cópia só conta mesmo quando sabes que pode ser restaurada, por isso vale a pena experimentar de vez em quando.","also":["restaurar","restaurado","reposição","restore"]},{"id":"svcreview","g":"run","word":"Revisão do serviço","text":"Um olhar para trás sobre um mês de um serviço: incidentes abertos e resolvidos, a rapidez com que as pessoas tiveram resposta, disponibilidade e tokens usados. A Revisão mensal mostra isto para cada serviço.","also":["revisões do serviço","revisão mensal","revisões mensais"]},{"id":"accessreview","g":"run","word":"Revisão de acessos","text":"Verificar de 90 em 90 dias quem ainda consegue entrar: ligações partilhadas, funções de amigos e palavras-passe e chaves guardadas. Manténs ou removes cada um, para o acesso antigo não ficar esquecido.","also":["revisões de acessos","revisão de acesso"]},{"id":"improvements","g":"run","word":"Lista de melhorias","text":"Tudo o que a equipa decidiu melhorar, num só sítio: sugestões da retrospetiva, ações das revisões e correções de problemas, cada uma com o seu estado. Está em 📈 Melhorias.","also":["listas de melhorias","melhorias"]},{"id":"tokencap","g":"run","word":"Limite de tokens","text":"Um limite mensal para os tokens que os agentes de um serviço podem usar. Aos 80% recebes um aviso; aos 100% o trabalho deles em segundo plano espera pelo mês seguinte ou até aumentares o limite.","also":["limites de tokens","limite mensal de tokens"]},{"id":"svcmgmt","g":"run","word":"Gestão de serviços","text":"Tudo o que é preciso para manter um serviço útil e a funcionar para quem depende dele, dia após dia.","also":["gerir um serviço"]},{"id":"itil","g":"run","word":"ITIL","text":"Um guia muito usado de boas práticas na gestão de serviços, que cobre coisas como incidentes, problemas e mudanças. O nome já significou IT Infrastructure Library."},{"id":"itsm","g":"run","word":"Gestão de serviços de TI (ITSM)","text":"Gerir a tecnologia como um serviço para as pessoas, com formas claras de tratar pedidos, incidentes, mudanças e melhorias.","also":["ITSM","IT service management"]},{"id":"managed","g":"run","word":"Serviço gerido","text":"Um serviço que outra entidade opera e mantém por ti, ao abrigo de um acordo sobre o nível de qualidade que tem de ter.","also":["serviços geridos","managed service","managed services"]},{"id":"svcowner","g":"run","word":"Responsável pelo serviço","text":"A pessoa que responde por um serviço no seu todo: como funciona, quanto custa e como melhora.","also":["responsáveis pelo serviço","dono do serviço","service owner","service owners"]},{"id":"sla","g":"run","word":"Acordo de nível de serviço (SLA)","text":"Uma promessa escrita aos clientes sobre o desempenho de um serviço, como “no ar 99,9% do tempo” ou “resposta numa hora”, muitas vezes com devolução de dinheiro se não for cumprida.","also":["SLA","SLAs","service level agreement","acordo de nível de serviço"]},{"id":"slo","g":"run","word":"Objetivo de nível de serviço (SLO)","text":"A meta da própria equipa para o desempenho de um serviço durante um período, normalmente um pouco mais exigente do que o SLA, por segurança.","also":["SLO","SLOs","objetivo de nível de serviço"]},{"id":"sli","g":"run","word":"Indicador de nível de serviço (SLI)","text":"A medição real que comparas com uma meta, como a percentagem de visitas que carregaram bem.","also":["SLI","SLIs","indicador de nível de serviço"]},{"id":"availability","g":"run","word":"Disponibilidade","text":"Se as pessoas conseguem usar um serviço quando precisam, muitas vezes medida como uptime.","also":["alta disponibilidade","availability","high availability"]},{"id":"downtime","g":"run","word":"Tempo de inatividade (downtime)","text":"O tempo em que um serviço não funciona ou está desligado, planeado ou não.","also":["downtime","down time","inatividade"]},{"id":"errorbudget","g":"run","word":"Orçamento de erros","text":"A pequena margem de falha que a tua meta de fiabilidade permite. Enquanto sobrar alguma, podes arriscar nas mudanças; quando acaba, abrandas.","also":["orçamentos de erros","error budget","error budgets"]},{"id":"outage","g":"run","word":"Falha de serviço (outage)","text":"Um período em que um serviço está em baixo ou muito avariado para os seus utilizadores.","also":["outage","outages","interrupção","interrupções"]},{"id":"degraded","g":"run","word":"Degradado","text":"A funcionar, mas mal: lento, ou com algumas partes que não funcionam.","also":["serviço degradado","degraded","degraded service"]},{"id":"monitoring","g":"run","word":"Monitorização","text":"Vigiar um serviço automaticamente o tempo todo, para os problemas serem detetados, idealmente antes de os utilizadores darem por eles.","also":["monitorizar","monitoring"]},{"id":"observability","g":"run","word":"Observabilidade","text":"A capacidade de perceber o que se passa dentro de um sistema olhando de fora, através dos seus registos, números e rastos.","also":["o11y","observability"]},{"id":"log","g":"run","word":"Registo (log)","text":"Um diário que um programa vai escrevendo sobre o que está a fazer, usado para descobrir o que correu mal.","also":["log","logs","logging","registos"],"noTip":1},{"id":"trace","g":"run","word":"Rasto (trace)","text":"O registo do caminho que um pedido faz pelas diferentes partes de um sistema, passo a passo, a mostrar onde abrandou.","also":["trace","traces","tracing","rastreio"]},{"id":"latency","g":"run","word":"Latência","text":"O tempo que algo demora a responder, como a espera entre clicares e a página aparecer.","also":["latency"]},{"id":"alert","g":"run","word":"Alerta","text":"Uma mensagem automática a dizer que algo precisa de atenção, como o site não responder.","also":["alertas","alert","alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Fadiga de alertas","text":"Quando há tantos alertas que as pessoas começam a ignorá-los, incluindo os importantes.","also":["fadiga de alarmes","alert fatigue","alarm fatigue"]},{"id":"dashboard","g":"run","word":"Painel (dashboard)","text":"Um ecrã que mostra, de relance, os números e estados mais importantes.","also":["dashboard","dashboards","painéis"],"noTip":1},{"id":"paging","g":"run","word":"Chamada de urgência (paging)","text":"Chamar ou acordar com urgência a pessoa de prevenção por causa de um problema.","also":["paging","paged","acionar"]},{"id":"escalation","g":"run","word":"Escalonamento","text":"Chamar alguém com mais competência ou autoridade quando um problema não se resolve ao nível atual, ou não com a rapidez necessária.","also":["escalar","escalation","escalate","escalated"]},{"id":"triage","g":"run","word":"Triagem","text":"Ordenar depressa os problemas que chegam consoante a urgência e a importância, para tratar primeiro os piores.","also":["triage","triaged","fazer a triagem"]},{"id":"impact","g":"run","word":"Impacto","text":"O quanto algo afeta as pessoas: a quantas, e quão gravemente.","noTip":1},{"id":"urgency","g":"run","word":"Urgência","text":"A rapidez com que algo tem de ser tratado. O impacto e a urgência juntos definem a prioridade.","noTip":1},{"id":"plevels","g":"run","word":"Níveis de prioridade (P1, P2…)","text":"Etiquetas para o grau de urgência de um problema. P1 é o mais grave e pede ação imediata.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Fila de tickets","text":"A lista de pedidos e incidentes à espera de serem atendidos.","also":["filas de tickets","ticket queue","ticket queues"]},{"id":"tiers","g":"run","word":"Primeira e segunda linha","text":"Níveis de apoio: a primeira linha atende a chamada e resolve o simples; a segunda linha tem competências mais fundas para o mais difícil. Também se diz nível 1 e nível 2.","also":["primeira linha","segunda linha","apoio de primeira linha","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Comandante do incidente","text":"A pessoa que lidera a resposta a um incidente, para todos saberem quem decide e quem faz o quê.","also":["comandantes do incidente","incident commander","incident commanders"]},{"id":"responsetime","g":"run","word":"Tempo de resposta","text":"O tempo que passa até alguém pegar pela primeira vez num pedido ou incidente.","also":["tempos de resposta","response time","response times"]},{"id":"resolution","g":"run","word":"Tempo de resolução","text":"O tempo que demora a resolver por completo um pedido ou incidente, desde o relato até estar corrigido.","also":["tempos de resolução","resolution time","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Tempo médio de recuperação (MTTR)","text":"Em média, quanto tempo leva a pôr um serviço a funcionar outra vez depois de avariar. O MTTR pode querer dizer coisas ligeiramente diferentes, por isso diz o que medes.","also":["MTTR","mean time to restore","mean time to recover"]},{"id":"mtbf","g":"run","word":"Tempo médio entre falhas (MTBF)","text":"Em média, quanto tempo um serviço funciona até algo avariar.","also":["MTBF","mean time between failures"]},{"id":"cmdb","g":"run","word":"Base de dados de gestão de configurações (CMDB)","text":"A lista de todos os teus itens de configuração e de como se ligam, para veres o que depende de quê.","also":["CMDB","configuration management database"]},{"id":"asset","g":"run","word":"Ativo (asset)","text":"Qualquer coisa de valor que tens ou pagas para manter o serviço a funcionar, como um portátil, uma licença de software ou um domínio.","also":["ativos","asset","assets"],"noTip":1},{"id":"capplan","g":"run","word":"Planeamento de capacidade","text":"Garantir que haverá poder de computação, armazenamento e pessoas suficientes para o que aí vem.","also":["plano de capacidade","capacity planning","capacity plan"]},{"id":"scaling","g":"run","word":"Escalar (scaling)","text":"Aguentar mais utilizadores dando mais poder a uma máquina (escalar na vertical) ou juntando mais máquinas (escalar na horizontal).","also":["escalabilidade","escalar na vertical","escalar na horizontal","scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Continuidade de negócio","text":"Planos para manter o essencial a funcionar quando algo grande corre mal, como perder um escritório, um fornecedor importante ou os computadores.","also":["plano de continuidade de negócio","business continuity","business continuity plan"]},{"id":"dr","g":"run","word":"Recuperação de desastres (DR)","text":"O plano e as ferramentas para recuperar um serviço depois de algo grave, como perder um centro de dados inteiro.","also":["DR","disaster recovery","recuperação após desastre"]},{"id":"rto","g":"run","word":"Tempo objetivo de recuperação (RTO)","text":"O tempo máximo que um serviço pode estar em baixo depois de um desastre, antes de ter de voltar a funcionar.","also":["RTO","recovery time objective"]},{"id":"rpo","g":"run","word":"Ponto objetivo de recuperação (RPO)","text":"Quantos dados recentes podes perder sem grande problema, medido em tempo. Um RPO de uma hora quer dizer cópias de segurança pelo menos a cada hora.","also":["RPO","recovery point objective"]},{"id":"redundancy","g":"run","word":"Redundância","text":"Ter reservas à mão, como um segundo servidor, para que uma falha não pare o serviço.","also":["redundante","redundancy"]},{"id":"failover","g":"run","word":"Failover (comutação por falha)","text":"Passar sozinho para um sistema de reserva quando o habitual falha.","also":["failover","fail over","comutação por falha"]},{"id":"spof","g":"run","word":"Ponto único de falha","text":"Uma peça que leva tudo consigo quando avaria, porque não há reserva.","also":["pontos únicos de falha","SPOF","single point of failure","single points of failure"]},{"id":"maintwin","g":"run","word":"Janela de manutenção","text":"Um período planeado em que um serviço pode ficar parado ou lento para manutenção, avisado aos utilizadores com antecedência.","also":["janelas de manutenção","manutenção planeada","maintenance window","maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Passagem de testemunho (handover)","text":"Passar trabalho, conhecimento e responsabilidade a outra pessoa ou equipa, para que nada se perca.","also":["handover","handovers","passagem de testemunho","passagem de turno"]},{"id":"kb","g":"run","word":"Base de conhecimento","text":"Uma coleção de artigos de ajuda e respostas, para os utilizadores e para a equipa.","also":["bases de conhecimento","knowledge base","knowledge bases"]},{"id":"csat","g":"run","word":"Satisfação do cliente (CSAT)","text":"Uma nota dada pelos utilizadores a dizer quão satisfeitos ficaram, muitas vezes pedida depois de um pedido ser fechado.","also":["CSAT","customer satisfaction"]},{"id":"supplier","g":"run","word":"Fornecedor","text":"Uma empresa externa de que dependes, como o teu fornecedor de alojamento. Também se diz vendor ou terceiro.","also":["fornecedores","terceiros","terceiro","supplier","suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Desativação de um serviço","text":"Desligar um serviço de vez, em segurança: avisar os utilizadores, tratar dos dados e dos acessos e parar os custos.","also":["desativar um serviço","service retirement","retiring a service"]},{"id":"eol","g":"run","word":"Fim de vida (EOL)","text":"Quando um produto deixa de receber atualizações ou apoio do fabricante, e por isso deve ser substituído.","also":["EOL","end of life","end-of-life"]},{"id":"cybersec","g":"sec","word":"Cibersegurança","text":"Proteger sistemas e dados contra invasões, roubo ou danos.","also":["segurança informática","cybersecurity","cyber security"]},{"id":"authn","g":"sec","word":"Autenticação","text":"Verificar quem alguém é, normalmente com uma palavra-passe ou um código. Muitas vezes abreviado para authn.","also":["authn","authentication"]},{"id":"authz","g":"sec","word":"Autorização","text":"Verificar o que alguém pode fazer depois de saberes quem é. Muitas vezes abreviado para authz.","also":["authz","authorisation","authorization"]},{"id":"mfa","g":"sec","word":"Autenticação multifator (MFA)","text":"Entrar com duas ou mais provas, como uma palavra-passe mais um código no telemóvel. Também se diz autenticação de dois fatores (2FA).","also":["MFA","2FA","dois fatores","autenticação de dois fatores","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Início de sessão único (SSO)","text":"Iniciar sessão uma só vez para entrar em muitos sistemas, como usar a conta do trabalho em todo o lado.","also":["SSO","single sign-on","login único"]},{"id":"pwmgr","g":"sec","word":"Gestor de palavras-passe","text":"Uma aplicação que cria palavras-passe fortes e se lembra delas por ti.","also":["gestores de palavras-passe","password manager","password managers"]},{"id":"secret","g":"sec","word":"Segredo (secret)","text":"Uma palavra-passe, chave ou outro código privado que um programa usa para entrar em algum lado. Nunca deve ser partilhado nem escrito no código.","also":["segredos","secret","secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"Chave de API","text":"Um código secreto que deixa um programa usar a API de outro serviço e mostra quem a está a usar (e a pagar).","also":["chaves de API","API key","API keys"]},{"id":"accesstoken","g":"sec","word":"Token de acesso","text":"Um passe temporário que prova que um programa tem autorização para entrar, para não precisar da tua palavra-passe de cada vez. Não é o mesmo que um token de IA.","also":["tokens de acesso","access token","access tokens"]},{"id":"encryption","g":"sec","word":"Encriptação","text":"Baralhar a informação para que só quem tem a chave certa a consiga ler.","also":["cifragem","encriptar","cifrar","encrypted","encrypt","encryption"]},{"id":"https","g":"sec","word":"HTTPS","text":"A forma segura de as páginas web viajarem, indicada pelo cadeado no navegador, para ninguém pelo caminho as poder ler ou alterar."},{"id":"cert","g":"sec","word":"Certificado SSL/TLS","text":"Um cartão de identificação digital que permite a um site provar quem é e usar HTTPS. Expira, por isso tem de ser renovado.","also":["certificado TLS","certificado SSL","certificado","certificados","TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Permissões","text":"As regras sobre quem pode ver ou alterar o quê.","also":["permissão","permission","permissions"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Privilégio mínimo","text":"Dar a cada pessoa ou programa só o acesso de que realmente precisa, e só durante o tempo de que precisa.","also":["princípio do privilégio mínimo","least privilege","principle of least privilege"]},{"id":"rbac","g":"sec","word":"Controlo de acesso por funções (RBAC)","text":"Dar acesso por função, como leitor ou editor, em vez de pessoa a pessoa.","also":["RBAC","acesso por funções","role-based access"]},{"id":"vuln","g":"sec","word":"Vulnerabilidade","text":"Uma fraqueza que alguém pode usar para invadir ou causar danos.","also":["vulnerabilidades","vulnerability","vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day (dia zero)","text":"Uma fraqueza que os atacantes conhecem antes de os criadores terem tido tempo para a corrigir.","also":["zero-days","zero day","dia zero"]},{"id":"malware","g":"sec","word":"Malware (software malicioso)","text":"Software nocivo, como os vírus, feito para danificar, espiar ou roubar.","also":["software malicioso"]},{"id":"ransomware","g":"sec","word":"Ransomware (sequestro de dados)","text":"Malware que tranca os teus ficheiros e exige dinheiro para os destrancar. As boas cópias de segurança são a melhor defesa.","also":["ataque de ransomware","sequestro de dados","ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Mensagens falsas que tentam enganar-te para dares palavras-passe ou dinheiro, ou abrires algo nocivo.","also":["email de phishing","emails de phishing","phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Engenharia social","text":"Enganar pessoas, em vez de computadores, para obter acesso, como uma chamada falsa do “apoio informático”."},{"id":"firewall","g":"sec","word":"Firewall (barreira de proteção)","text":"Um guarda que decide que tráfego da rede pode entrar ou sair.","also":["firewalls","barreira de proteção"]},{"id":"vpn","g":"sec","word":"VPN","text":"Sigla de “rede privada virtual”: uma ligação privada e cifrada pela internet, muitas vezes usada para chegar com segurança aos sistemas do trabalho.","also":["rede privada virtual","virtual private network"]},{"id":"ddos","g":"sec","word":"Negação de serviço (DoS, DDoS)","text":"Inundar um serviço com tanto tráfego falso que as pessoas verdadeiras não o conseguem usar. DDoS quer dizer que vem de muitos computadores ao mesmo tempo.","also":["DoS","DDoS","negação de serviço","denial of service","DDoS attack","ataque DDoS"]},{"id":"pentest","g":"sec","word":"Teste de intrusão (pen test)","text":"Contratar especialistas de confiança para tentarem invadir, de modo a encontrar as fraquezas antes de os atacantes verdadeiros as encontrarem.","also":["pen test","pen testing","penetration testing","pentest","teste de penetração","testes de intrusão"]},{"id":"audit","g":"sec","word":"Auditoria de segurança","text":"Uma verificação cuidadosa de quão bem algo está protegido, face a uma lista de boas práticas.","also":["auditorias de segurança","security audit","security audits"]},{"id":"threatmodel","g":"sec","word":"Modelação de ameaças","text":"Pensar em quem poderia atacar algo, como, e o que farias para o impedir.","also":["modelo de ameaças","threat modelling","threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Violação de dados","text":"Quando informação privada chega a quem não devia, ou é perdida ou alterada sem autorização.","also":["violações de dados","fuga de dados","data breach","data breaches"]},{"id":"pii","g":"sec","word":"Dados pessoais","text":"Qualquer informação sobre uma pessoa que possa ser identificada, como um nome, um endereço de email ou uma localização. Também se diz PII.","also":["PII","informação de identificação pessoal","personally identifiable information","personal data"]},{"id":"gdpr","g":"sec","word":"RGPD","text":"A lei europeia sobre dados pessoais (o Reino Unido tem a sua própria versão): recolher só o que é preciso, guardá-lo em segurança e deixar as pessoas ver ou apagar os seus.","also":["GDPR","Regulamento Geral sobre a Proteção de Dados","General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Proteção de dados","text":"Cuidar bem dos dados pessoais e dentro da lei.","also":["lei da proteção de dados","data protection","data protection law"]},{"id":"privacypolicy","g":"sec","word":"Política de privacidade","text":"Uma página pública que diz que dados pessoais recolhes, porquê e o que fazes com eles.","also":["declaração de privacidade","aviso de privacidade","privacy policy","privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Consentimento","text":"O sim claro e livre de uma pessoa a que os seus dados sejam usados de uma determinada maneira. Pode retirá-lo a qualquer momento.","also":["opt-in","consent"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"Um pequeno ficheiro que um site guarda no teu navegador para se lembrar de coisas, como teres sessão iniciada. Alguns precisam primeiro do teu consentimento.","also":["cookies","testemunho de ligação"],"noTip":1},{"id":"minimisation","g":"sec","word":"Minimização de dados","text":"Recolher e guardar só os dados pessoais de que realmente precisas para o trabalho.","also":["data minimisation","data minimization"]},{"id":"retention","g":"sec","word":"Conservação de dados","text":"Durante quanto tempo os dados são guardados antes de serem apagados. Não os guardar mais do que o necessário é mais seguro e muitas vezes é a lei.","also":["retenção de dados","prazo de conservação","data retention","retention period"]},{"id":"anon","g":"sec","word":"Anonimização","text":"Alterar os dados de modo a que ninguém possa ser razoavelmente identificado a partir deles.","also":["anonimizado","dados anónimos","anonymisation","anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonimização","text":"Trocar nomes e outros detalhes por códigos, com uma chave guardada à parte para os voltar a ligar. Continuam a ser dados pessoais.","also":["pseudonimizado","pseudonymisation","pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Acordo de tratamento de dados (DPA)","text":"Um contrato que diz como um fornecedor pode tratar dados pessoais em teu nome.","also":["DPA","data processing agreement","acordo de subcontratação"]},{"id":"dpia","g":"sec","word":"Avaliação de impacto sobre a proteção de dados (AIPD)","text":"Uma análise cuidadosa, antes de começares, de como um plano para usar dados pessoais pode afetar as pessoas e de como reduzir os riscos.","also":["AIPD","DPIA","data protection impact assessment"]},{"id":"auditlog","g":"sec","word":"Registo de auditoria","text":"Um registo de quem fez o quê e quando, para as ações poderem ser verificadas mais tarde.","also":["registos de auditoria","rasto de auditoria","audit log","audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Conformidade (compliance)","text":"Cumprir as leis, regras e normas que se aplicam a ti e saber demonstrar que o fazes.","also":["compliance","conforme","cumprimento normativo","compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Uma norma internacional muito conhecida para gerir a segurança da informação. As empresas podem ser certificadas segundo ela.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Um relatório norte-americano, verificado por auditores externos, que mostra que uma empresa trata bem dos dados dos clientes.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agente","text":"Uma IA que trabalha numa tarefa sozinha: lê o código, faz alterações, corre verificações e diz-te o que fez. O trabalho dela continua a ser verificado.","also":["agentes","agent"]},{"id":"token","g":"ai","word":"Token","text":"Os pedacinhos de texto que uma IA lê e escreve, cada um com cerca de três quartos de uma palavra. A utilização de IA conta-se em tokens, por isso menos tokens deixam mais do teu plano.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Um pequeno comando que corre sozinho num momento definido, por exemplo quando começa uma sessão de IA, para a equipa ouvir os teus comentários.","also":["hooks"]},{"id":"ai","g":"ai","word":"Inteligência artificial (IA)","text":"Sistemas informáticos que fazem coisas que normalmente achamos que precisam de uma pessoa, como escrever, responder a perguntas ou reconhecer imagens.","also":["IA","AI","artificial intelligence","inteligência artificial"],"noTip":1},{"id":"ml","g":"ai","word":"Aprendizagem automática (ML)","text":"Uma forma de fazer os computadores aprenderem padrões a partir de muitos exemplos, em vez de lhes dar regras exatas.","also":["ML","machine learning","aprendizagem de máquina"]},{"id":"model","g":"ai","word":"Modelo","text":"O “cérebro” treinado de um sistema de IA, criado ao aprender com um número enorme de exemplos. Os modelos diferem em capacidade, rapidez e preço.","also":["modelos","modelo de IA","model","models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Modelo de linguagem de grande escala (LLM)","text":"Um modelo de IA treinado com quantidades enormes de texto, para conseguir ler e escrever linguagem.","also":["LLM","LLMs","modelo de linguagem"]},{"id":"genai","g":"ai","word":"IA generativa","text":"IA que cria coisas novas, como textos, imagens ou código, e não apenas as ordena ou reconhece.","also":["GenAI","IA gen","generative AI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"Um programa com que falas na linguagem de todos os dias, escrevendo ou falando.","also":["chatbots","robô de conversa"]},{"id":"prompt","g":"ai","word":"Prompt (instrução)","text":"Aquilo que dás a uma IA: a tua pergunta ou instruções, mais o que lhe entregares. Prompts mais claros costumam dar melhores respostas.","also":["prompts","instrução","instruções"]},{"id":"prompteng","g":"ai","word":"Engenharia de prompts","text":"A arte de escrever prompts que dão resultados fiáveis e úteis.","also":["prompt engineering"]},{"id":"sysprompt","g":"ai","word":"Prompt de sistema","text":"Instruções de fundo que uma IA recebe antes de a conversa começar, a definir o seu papel e as suas regras. Pesam mais do que aquilo que escreves.","also":["prompts de sistema","instruções de sistema","system prompt","system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Contexto","text":"Tudo o que a IA consegue ver enquanto trabalha: as instruções, as tuas mensagens, os ficheiros que leu e as respostas anteriores.","noTip":1},{"id":"ctxwin","g":"ai","word":"Janela de contexto","text":"A quantidade de coisas que uma IA consegue ter presente de uma vez, medida em tokens. Para lá disso, as partes mais antigas são postas de lado ou resumidas.","also":["janelas de contexto","context window","context windows"]},{"id":"session","g":"ai","word":"Sessão","text":"Uma conversa de trabalho com uma IA, do princípio ao fim. Uma sessão nova começa com a memória em branco.","also":["sessões","session","sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Memória","text":"Notas que uma IA guarda entre sessões, para se lembrar das tuas preferências e das decisões passadas.","noTip":1},{"id":"hallucination","g":"ai","word":"Alucinação","text":"Quando uma IA diz algo que parece muito seguro mas é inventado ou errado. Confirma os factos importantes.","also":["alucinações","alucinar","hallucination","hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Treino","text":"Ensinar um modelo mostrando-lhe um número enorme de exemplos, antes de alguém o usar.","also":["treinar","treinado","training","trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Dados de treino","text":"Os exemplos com que um modelo aprendeu. O que ele sabe fica pela data em que esses dados foram recolhidos.","also":["conjunto de treino","training data","training set"]},{"id":"cutoff","g":"ai","word":"Data limite do conhecimento","text":"A data em que acaba o conhecimento de origem de uma IA. Não saberá o que aconteceu depois, a menos que o procure.","also":["limite de treino","knowledge cutoff","training cutoff"]},{"id":"finetune","g":"ai","word":"Afinação (fine-tuning)","text":"Treino extra de um modelo já existente com os teus próprios exemplos, para o tornar melhor num trabalho em particular.","also":["fine-tuning","afinar","fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inferência","text":"Um modelo de IA a ser realmente usado para responder a algo, por oposição a estar a ser treinado.","also":["inferência do modelo","inference","model inference"]},{"id":"tooluse","g":"ai","word":"Uso de ferramentas","text":"Uma IA que consegue fazer coisas, e não apenas falar: executar comandos, ler ficheiros ou pesquisar na web, através das ferramentas que a aplicação lhe dá.","also":["chamada de ferramentas","chamadas de ferramentas","tool use","tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagente","text":"Uma IA ajudante a quem uma IA principal entrega uma tarefa mais pequena e de quem recebe o resultado.","also":["subagentes","subagent","subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multiagente","text":"Várias IAs a trabalhar juntas numa mesma tarefa, cada uma com a sua parte, como uma pequena equipa.","also":["sistema multiagente","multi-agent","multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomia","text":"O que uma IA pode fazer por si antes de ter de perguntar a uma pessoa.","also":["autónomo","autonomy","autonomous"]},{"id":"hitl","g":"ai","word":"Humano no circuito (human in the loop)","text":"Manter uma pessoa envolvida para verificar ou aprovar o que a IA faz em momentos-chave. No AI-gile, és tu.","also":["human in the loop","human-in-the-loop","HITL","pessoa no circuito"]},{"id":"guardrails","g":"ai","word":"Barreiras de segurança (guardrails)","text":"Limites e verificações que mantêm seguras as ações de uma IA, como pedir aprovação antes de algo ir para o ar. Reduzem o risco de erros, mas não os eliminam.","also":["guardrails","guardrail","limites de segurança"]},{"id":"rag","g":"ai","word":"Geração com recuperação de informação (RAG)","text":"Deixar uma IA consultar os teus próprios documentos antes de responder, para as respostas assentarem nos teus factos.","also":["RAG","retrieval augmented generation","retrieval-augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding (representação numérica)","text":"Transformar texto numa lista de números que capta o seu significado, para o computador encontrar coisas com significados parecidos.","also":["embeddings","representação numérica","vetor de significado"]},{"id":"vectordb","g":"ai","word":"Base de dados vetorial","text":"Uma base de dados feita para pesquisar essas listas de números (embeddings), a fim de encontrar material com um significado parecido.","also":["bases de dados vetoriais","vector database","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Uma forma comum de ligar ferramentas e fontes de dados a aplicações de IA, para que uma IA as possa usar.","also":["MCP","protocolo de contexto de modelo"]},{"id":"temperature","g":"ai","word":"Temperatura","text":"Uma definição de quão aventureiras são as respostas de uma IA. Baixa dá respostas mais estáveis e previsíveis; alta dá respostas mais variadas. Nenhuma garante que acerta sempre.","also":["temperatura do modelo","temperature","model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Capaz de trabalhar com mais de um tipo de informação, como texto, imagens e som.","also":["multi-modal","multimodal"]},{"id":"evals","g":"ai","word":"Avaliação (eval)","text":"Um teste planeado ao desempenho de uma IA em exemplos escolhidos, para poderes comparar modelos ou prompts.","also":["avaliações","eval","evals"]},{"id":"bias","g":"ai","word":"Enviesamento (bias)","text":"Quando uma IA (ou uma pessoa) tende injustamente para um lado, muitas vezes por causa daquilo com que aprendeu.","also":["viés","enviesado","bias","biased"],"noTip":1},{"id":"responsible","g":"ai","word":"IA responsável","text":"Usar a IA com justiça, segurança e honestidade, com as pessoas a continuarem a responder pelos resultados.","also":["IA ética","responsible AI","ethical AI"]},{"id":"injection","g":"ai","word":"Injeção de prompts (prompt injection)","text":"Um truque em que instruções escondidas numa página web ou ficheiro tentam levar uma IA a fazer algo que o utilizador não pediu.","also":["prompt injection","prompt injections","injeção de instruções"]},{"id":"ratelimit","g":"ai","word":"Limite de pedidos (rate limit)","text":"Um teto para o número de pedidos que podes enviar a um serviço num dado tempo. Se o ultrapassares, tens de esperar.","also":["rate limit","rate limits","rate limited","limites de pedidos"]},{"id":"usagelimit","g":"ai","word":"Limite de utilização","text":"Quanto trabalho de IA o teu plano permite num período, depois do qual faz uma pausa ou custa mais.","also":["limites de utilização","usage limit","usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Criar software descrevendo à IA, quase só por palavras, o que queres e deixando-a escrever o código.","also":["vibe-coding","programar por intuição"]},{"id":"budget","g":"money","word":"Orçamento","text":"A quantia de dinheiro posta de parte para algo.","also":["orçamentos","budget","budgets"],"noTip":1},{"id":"costest","g":"money","word":"Estimativa de custos","text":"Um palpite do que algo vai custar antes de começares.","also":["estimativas de custos","cost estimate","cost estimates"]},{"id":"roi","g":"money","word":"Retorno do investimento (ROI)","text":"O que recebes de volta em comparação com o que puseste. Se for positivo, valeu a pena.","also":["ROI","return on investment"]},{"id":"tco","g":"money","word":"Custo total de propriedade (TCO)","text":"Tudo o que algo realmente custa durante toda a sua vida, e não só o preço de compra: funcionamento, apoio, atualizações e, no fim, a desativação.","also":["TCO","total cost of ownership"]},{"id":"capex","g":"money","word":"CapEx e OpEx","text":"CapEx é o dinheiro gasto de início em coisas que ficas a ter; OpEx é a despesa contínua, como as contas mensais.","also":["CapEx","OpEx","despesa de capital","despesa operacional","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Subscrição","text":"Pagar com regularidade, normalmente todos os meses ou anos, para continuar a usar algo.","also":["subscrições","assinatura","subscription","subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Software como serviço (SaaS)","text":"Software que usas online e pagas por subscrição, enquanto o fabricante o faz funcionar por ti.","also":["SaaS","software as a service"]},{"id":"payg","g":"money","word":"Pagamento por utilização","text":"Pagar só o que usas, como na computação em nuvem ou nos tokens de IA.","also":["pay as you go","pay-as-you-go","usage-based pricing","pagar conforme o uso"]},{"id":"overage","g":"money","word":"Excedente","text":"Utilização acima do que o teu plano inclui, que pode custar mais.","also":["excedentes","custos de excedente","overage","overages","overage charges"]},{"id":"billingalert","g":"money","word":"Alerta de faturação","text":"Uma mensagem quando os gastos ou a utilização chegam a um nível que escolheste. Avisa-te, mas nem sempre impede novos custos.","also":["alertas de faturação","alerta de gastos","billing alert","billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Nível gratuito","text":"Um nível grátis de um serviço pago, com limites. Útil para começar.","also":["plano gratuito","free tier","free plan"]},{"id":"pricing","g":"money","word":"Plano de preços","text":"Os diferentes pacotes que um serviço vende, cada um com o seu preço e limites.","also":["planos de preços","pricing plan","pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licença","text":"As regras sobre como podes usar, copiar, alterar ou partilhar algo que outra pessoa criou, como software, tipos de letra ou imagens.","also":["licenças","licence","licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Código aberto (open source)","text":"Software cujo código qualquer pessoa pode ler, usar e muitas vezes alterar de graça, segundo as regras da sua licença.","also":["open source","open-source","software livre","software de código aberto","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Licença de código aberto","text":"As regras que acompanham o código aberto. Algumas deixam fazer quase tudo (como a MIT); outras pedem que partilhes também as tuas alterações (como a GPL).","also":["licenças de código aberto","licença MIT","GPL","open source licence","open source licences","MIT licence"]},{"id":"proprietary","g":"money","word":"Proprietário","text":"Pertence a uma empresa e não é livre de copiar ou alterar. O contrário de código aberto.","also":["software proprietário","proprietary","proprietary software"]},{"id":"copyright","g":"money","word":"Direitos de autor","text":"O direito legal de quem cria uma obra a controlar as cópias do seu trabalho, incluindo código e textos.","also":["copyright","direito de autor","protegido por direitos de autor","copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Propriedade intelectual (PI)","text":"Ideias e criações que a lei trata como tendo dono, como código, desenhos, nomes e logótipos.","also":["PI","IP","intellectual property","propriedade intelectual"]},{"id":"tos","g":"money","word":"Termos de serviço","text":"As regras que aceitas quando usas um serviço.","also":["termos e condições","termos de utilização","terms of service","terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Contrato","text":"Um acordo escrito entre duas partes que a lei faz respeitar.","also":["contratos","contract","contracts"],"noTip":1},{"id":"sow","g":"money","word":"Caderno de encargos (SOW)","text":"Um documento que define exatamente que trabalho vai ser feito, até quando e por quanto.","also":["SOW","statement of work","descrição do trabalho"]},{"id":"fixedprice","g":"money","word":"Preço fixo","text":"Um preço combinado para o trabalho todo, demore o que demorar.","also":["fixed price","fixed-price","preço fechado"]},{"id":"tm","g":"money","word":"Tempo e materiais","text":"Pagar as horas realmente trabalhadas e as coisas realmente usadas, em vez de um preço fixo.","also":["T&M","time and materials","por horas"]},{"id":"invoice","g":"money","word":"Fatura","text":"Uma conta que pede o pagamento de trabalho feito ou de bens fornecidos.","also":["faturas","invoice","invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Dependência do fornecedor (lock-in)","text":"Quando sair de um fornecedor é tão difícil ou caro que, na prática, já não consegues largá-lo.","also":["lock-in","vendor lock-in","aprisionamento tecnológico"]},{"id":"procurement","g":"money","word":"Compras e contratação","text":"O processo de escolher e comprar a fornecedores.","also":["aquisições","aprovisionamento","procurement"]},{"id":"servicecredit","g":"money","word":"Crédito de serviço","text":"Dinheiro de volta ou um desconto que recebes quando um fornecedor falha o SLA.","also":["créditos de serviço","service credit","service credits"]}]}};
